    private void milestoneOneProgramStillLowers() {
        CompilationArtifact artifact = compile(validProgram(42));
        assertTrue(artifact.successful(), messages(artifact));
        IrReturnTerminator terminator = (IrReturnTerminator) artifact.program().orElseThrow()
                .entryPoint().orElseThrow().blocks().getFirst().terminator();
        IrConstant value = (IrConstant) terminator.value().orElseThrow();
        assertEquals(42, value.value(), "typed IR return value");
        assertContains(artifact.llvmIr().orElseThrow(),
                "define i32 @main(i32 %argc, ptr %argv)", "native entry point");
        assertContains(artifact.llvmIr().orElseThrow(),
                "call ptr @ironwood_process_arguments", "process argument construction");
        assertContains(artifact.llvmIr().orElseThrow(), "ret i32 42", "LLVM return instruction");
    }

    private void commentsAndWhitespaceAreAccepted() {
        CompilationArtifact artifact = compile("""
                /* class-level comment */
                class Main {
                    // entry point
                    public static int main(String[] args) {
                        return 7; /* result */
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
    }

    private void parametersAndBooleansAreAccepted() {
        CompilationArtifact artifact = compile("""
                class Main {
                    public static int main(String[] args) { return choose(true, 4); }
                    static int choose(boolean enabled, int value) {
                        if (enabled) { return value; } else { return 0; }
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
    }

    private void overrideDirectivePreservesParserFlags() {
        var parsed = parseOnly("""
                abstract class Base { abstract int value(); }
                interface Parent { int count(); }
                interface Refined extends Parent {
                    @Override
                    int count();
                }
                abstract class Middle extends Base {
                    @ /* built-in directive */ Override abstract int value();
                }
                class Concrete extends Middle implements Refined {
                    @Override int value() { return 40; }
                    public @Override int count() { return 2; }
                }
                class Override { int value() { return 1; } }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var refined = (ironwood.compiler.ast.InterfaceDeclaration)
                parsed.unit().orElseThrow().declarations().get(2);
        assertTrue(refined.methods().getFirst().hasOverrideDirective(),
                "interface @Override flag was not preserved");
        var middle = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().get(3);
        assertTrue(middle.methods().getFirst().hasOverrideDirective(),
                "abstract method @Override flag was not preserved");
        var concrete = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().get(4);
        assertTrue(concrete.methods().stream().allMatch(
                        ironwood.compiler.ast.MethodDeclaration::hasOverrideDirective),
                "same-line or interleaved @Override flag was not preserved");
    }

