    private void testDirectivePreservesParserFlags() {
        var parsed = parseOnly("""
                class Test { int value() { return 1; } }
                class Suite {
                    @Test private void firstCase() { }
                    public @Test void secondCase() { }
                    int Test() { return 2; }
                }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var suite = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().get(1);
        assertTrue(suite.methods().get(0).hasTestDirective(),
                "leading @Test flag was not preserved");
        assertTrue(suite.methods().get(1).hasTestDirective(),
                "interleaved @Test flag was not preserved");
        assertTrue(!suite.methods().get(2).hasTestDirective(),
                "ordinary Test identifier was treated as a directive");
    }

