    private void finalVariablesPreserveParserFlags() {
        var parsed = parseOnly("""
                class Main {
                    Main(final int seed) { }
                    int method(final int value, final String[] rest) {
                        final int local = 1;
                        try { return local; }
                        catch (final Failure failure) { return value; }
                    }
                }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var main = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().getFirst();
        assertTrue(main.constructors().getFirst().parameters().getFirst().isFinal(),
                "constructor final parameter flag was not preserved");
        var method = main.methods().getFirst();
        assertTrue(method.parameters().getFirst().isFinal(),
                "method final parameter flag was not preserved");
        assertTrue(method.parameters().getLast().isFinal(),
                "array final parameter flag was not preserved");
        var local = (ironwood.compiler.ast.LocalVariableDeclaration)
                method.body().orElseThrow().statements().getFirst();
        assertTrue(local.isFinal(), "final local flag was not preserved");
        var tryStatement = (ironwood.compiler.ast.TryStatement)
                method.body().orElseThrow().statements().getLast();
        assertTrue(tryStatement.catches().getFirst().isFinal(),
                "final catch parameter flag was not preserved");
    }

    private void multiCatchSyntaxPreservesAlternatives() {
        var parsed = parseOnly("""
                class FirstFailure { }
                class SecondFailure { }
                class Main {
                    static int read() {
                        try { return 1; }
                        catch (FirstFailure | SecondFailure failure) { return 2; }
                    }
                }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var main = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().getLast();
        var guarded = (ironwood.compiler.ast.TryStatement)
                main.methods().getFirst().body().orElseThrow().statements().getFirst();
        var caught = guarded.catches().getFirst();
        assertEquals(List.of("FirstFailure", "SecondFailure"),
                caught.types().stream().map(ironwood.compiler.ast.TypeName::displayName).toList(),
                "multi-catch alternatives");
        assertTrue(caught.isMultiCatch(), "multi-catch AST marker");
        assertTrue(caught.isFinal(), "multi-catch binding must be implicitly final");
        Set<String> dependencies = new TypeDependencyScanner().scan(parsed.unit().orElseThrow());
        assertTrue(dependencies.contains("FirstFailure")
                        && dependencies.contains("SecondFailure"),
                "multi-catch dependency scan omitted an alternative");
        assertParserDiagnostic("""
                class Main { static int read() {
                    try { return 1; } catch (Failure | ) { return 2; }
                } }
                """, "expected catch type after '|'");
    }

