    private void textBlocksNormalizeDecodeAndPool() throws Exception {
        String escapedDelimiterLine = "            " + '\\' + "\"\"\"";
        String rawClosingLine = "            path" + '\\' + "\"\"\";";
        String source = String.join("\n",
                "class Main {",
                "    public static int main(String[] args) {",
                "        String trailing = \"\"\"   ",
                "            Hello",
                "            world",
                "            \"\"\";",
                "        String leading = \"\"\"",
                "",
                "            Hello",
                "            world\"\"\";",
                "        String raw = r\"\"\"",
                "            \\d+\\s+\\w+",
                "            \"\"\";",
                "        String escaped = \"\"\"",
                "            tab=\\t",
                escapedDelimiterLine,
                "            \"\"\";",
                "        String markers = r\"\"\"",
                "            // text, not a comment",
                "            /* still text */ ${notInterpolation}",
                "            \"\"\";",
                "        String trimmed = r\"\"\"",
                "            value   \t",
                "            \"\"\";",
                "        String rawClosing = r\"\"\"",
                rawClosingLine,
                "        String same = \"Hello\\nworld\\n\";",
                "        return trailing == same ? 42 : 1;",
                "    }",
                "}");
        CompilationArtifact artifact = compileWithStandardLibrary(source,
                "ironwood.lang.String");
        assertTrue(artifact.successful(), messages(artifact));
        List<String> values = artifact.program().orElseThrow().stringConstants().stream()
                .map(constant -> constant.value()).toList();
        assertTrue(values.contains("Hello\nworld\n"),
                "closing-line text block did not retain its final newline");
        assertTrue(values.contains("\nHello\nworld"),
                "same-line closing delimiter did not suppress the final newline");
        assertTrue(values.contains("\\d+\\s+\\w+\n"),
                "raw text block interpreted backslashes");
        assertTrue(values.contains("tab=\t\n\"\"\"\n"),
                "cooked text block did not decode escapes after indentation");
        assertTrue(values.contains("// text, not a comment\n"
                        + "/* still text */ ${notInterpolation}\n"),
                "raw text block treated comment markers or interpolation syntax specially");
        assertTrue(values.contains("value\n"),
                "raw text block did not remove trailing incidental whitespace");
        assertTrue(values.contains("path\\"),
                "raw text block treated a backslash as escaping its closing delimiter");
        assertEquals(1, (int) values.stream().filter("Hello\nworld\n"::equals).count(),
                "decoded-equal ordinary and text-block literal pool count");

        String mixedLineEndings = "class Main {\r\n"
                + "  public static int main(String[] args) {\r"
                + "    String text = \"\"\"\r\n"
                + "      first\r"
                + "      second\r\n"
                + "      \"\"\";\r"
                + "    return 42;\r\n"
                + "  }\r"
                + "}\r\n";
        CompilationArtifact normalized = compileWithStandardLibrary(mixedLineEndings,
                "ironwood.lang.String");
        assertTrue(normalized.successful(), messages(normalized));
        assertTrue(normalized.program().orElseThrow().stringConstants().stream()
                        .anyMatch(constant -> constant.value().equals("first\nsecond\n")),
                "text block did not normalize CRLF and CR line terminators to LF");
    }

