    private void binaryIntegerLiteralSyntaxIsAccepted() {
        var parsed = parseOnly("""
                class Main {
                    static int values() {
                        int mask = 0b1010_0101;
                        long flags = 0B1111_0000l;
                        return mask;
                    }
                }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var main = (ironwood.compiler.ast.ClassDeclaration)
                parsed.unit().orElseThrow().declarations().getFirst();
        var statements = main.methods().getFirst().body().orElseThrow().statements();
        var mask = (ironwood.compiler.ast.LocalVariableDeclaration) statements.getFirst();
        var flags = (ironwood.compiler.ast.LocalVariableDeclaration) statements.get(1);
        assertEquals("0b1010_0101",
                ((ironwood.compiler.ast.IntegerLiteralExpression) mask.initializer()).text(),
                "lowercase binary literal text");
        assertEquals("0B1111_0000l",
                ((ironwood.compiler.ast.IntegerLiteralExpression) flags.initializer()).text(),
                "uppercase long binary literal text");
    }

