    private void overloadsResolveBySignature() {
        CompilationArtifact artifact = compile("""
                interface Value { int read(int value); int read(boolean value); }
                class Base { }
                class Child extends Base { }
                class Picker implements Value {
                    Picker() { this(10); }
                    Picker(int seed) { this.seed = seed; }
                    int seed;
                    @Override public int read(int value) { return seed + value; }
                    @Override public int read(boolean value) { if (value) { return seed; } return 0; }
                    int choose(Base value) { return 1; }
                    int choose(Child value) { return 2; }
                }
                class Main {
                    public static int main(String[] args) {
                        Picker picker = new Picker();
                        Child child = new Child();
                        return picker.read(2) + picker.read(true) + picker.choose(child);
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        var picker = artifact.program().orElseThrow().classes().stream()
                .filter(type -> type.name().equals("Picker")).findFirst().orElseThrow();
        long readSlots = picker.dispatchEntries().stream()
                .filter(entry -> entry.slot().methodName().equals("read")).count();
        assertEquals(2, (int) readSlots, "overloaded dispatch slot count");
        assertTrue(artifact.program().orElseThrow().functions().stream()
                        .filter(function -> function.ownerClass().equals("Picker"))
                        .filter(function -> function.sourceName().equals("read"))
                        .map(function -> function.linkageName()).distinct().count() == 2,
                "overloaded methods did not receive unique linkage names");

        CompilationArtifact eligible = compile("""
                class Base {
                    public int choose(Object value) { return 1; }
                }
                class Child extends Base {
                    private int choose(String value) { return 2; }
                }
                class Choice {
                    int selected;
                    public Choice(Object value) { selected = 1; }
                    private Choice(String value) { selected = 2; }
                    static int form(String value) { return 3; }
                    int form(Object value) { return 4; }
                }
                class Main {
                    public static int main(String[] args) {
                        Child child = new Child();
                        Choice choice = new Choice("value");
                        if (child.choose("value") != 1) { return 1; }
                        if (choice.selected != 1) { return 2; }
                        if (choice.form("value") != 4) { return 3; }
                        if (Choice.form("value") != 3) { return 4; }
                        return 0;
                    }
                }
                """);
        assertTrue(eligible.successful(), messages(eligible));
    }

