    private void referenceGenericsRetainTypedSubstitutions() {
        CompilationArtifact artifact = compile("""
                interface Source<T> { T get(); }
                class Box<T> implements Source<T> {
                    T value;
                    Box(T value) { this.value = value; }
                    @Override public T get() { return value; }
                    T[] array(int size) { return new T[size]; }
                }
                class Main {
                    public static int main(String[] args) {
                        String text = "generic";
                        Box<String> strings = new Box<String>(text);
                        Source<String> source = strings;
                        String value = source.get();
                        String[] values = strings.array(1);
                        values[0] = value;
                        Box<Box<String>> nested = new Box<Box<String>>(strings);
                        if (nested.get().get() == values[0]) { return 0; }
                        return 1;
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        var genericGet = artifact.program().orElseThrow().functions().stream()
                .filter(function -> function.ownerClass().equals("Box"))
                .filter(function -> function.sourceName().equals("get"))
                .findFirst().orElseThrow();
        assertTrue(genericGet.returnType().isTypeParameter(),
                "generic method return type was erased before typed IR");
        assertContains(artifact.llvmIr().orElseThrow(), "%\"ironwood.class.Box\" = type { ptr, ptr }",
                "shared generic native layout");

        CompilationArtifact classOverride = compile("""
                class Base<T> {
                    int choose(T value) { return 1; }
                }
                class Child extends Base<String> {
                    @Override int choose(String value) { return 42; }
                }
                class Main {
                    public static int main(String[] args) {
                        Base<String> value = new Child();
                        return value.choose("dispatch");
                    }
                }
                """);
        assertTrue(classOverride.successful(), messages(classOverride));
        var child = classOverride.program().orElseThrow().classes().stream()
                .filter(type -> type.name().equals("Child")).findFirst().orElseThrow();
        assertEquals(2, (int) child.dispatchEntries().stream()
                        .filter(entry -> entry.slot().methodName().equals("choose"))
                        .peek(entry -> assertTrue(entry.targetLinkageName().contains("Child.choose"),
                                "generic class ancestor slot did not select the substituted override"))
                        .count(),
                "generic class override should populate both erased dispatch slots");
    }

    private void primitiveGenericsSpecializeNativeShapes() {
        CompilationArtifact artifact = compile("""
                class Box<T> {
                    T value;
                    Box(T value) { this.value = value; }
                    T get() { return value; }
                    T[] pair(T other) {
                        T[] values = new T[2];
                        values[0] = value;
                        values[1] = other;
                        return values;
                    }
                }
                class Main {
                    public static int main(String[] args) {
                        Box<int> box = new Box<int>(40);
                        int[] values = box.pair(2);
                        return box.get() + values[1];
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        IrProgram program = artifact.program().orElseThrow();
        IrClass specialized = program.classes().stream()
                .filter(type -> type.name().equals("Box<specialization:int>"))
                .findFirst().orElseThrow();
        assertEquals(List.of(IrType.I32), specialized.fields().stream()
                        .map(field -> field.type()).toList(),
                "primitive specialized field layout");
        assertTrue(program.functions().stream()
                        .anyMatch(function -> function.linkageName()
                                .equals("ironwood.Box.get$specialization$C0_int")
                                && function.returnType().equals(IrType.I32)),
                "primitive specialized method ABI");
        assertTrue(program.arrayTypes().stream()
                        .anyMatch(array -> array.type().equals(IrType.array(IrType.I32))),
                "primitive generic array descriptor");
        String llvm = artifact.llvmIr().orElseThrow();
        assertContains(llvm, "%\"ironwood.class.Box<specialization:int>\" = type { ptr, i32 }",
                "primitive specialized LLVM layout");
        assertContains(llvm, "call i32 @\"ironwood.Box.get$specialization$C0_int\"",
                "primitive specialized LLVM call");
    }

    private void primitiveGenericInferenceAndConstructorsAreSpecialized() {
        CompilationArtifact artifact = compile("""
                class Value<T> {
                    T value;
                    <U> Value(U ignored, T value) { this.value = value; }
                    T get() { return value; }
                }
                class Utility {
                    static <T> T identity(T value) { return value; }
                    static int select(long value) { return 1; }
                    static <T> int select(T value) { return 2; }
                }
                class Main {
                    public static int main(String[] args) {
                        Value<int> value = new <long> Value<>(7L, 42);
                        int inferred = Utility.identity(value.get());
                        return Utility.select(inferred) == 2 ? inferred : 0;
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        List<String> linkages = artifact.program().orElseThrow().functions().stream()
                .map(IrFunction::linkageName).toList();
        assertTrue(linkages.contains(
                        "ironwood.Value.<init>$specialization$C0_int$M0_long"),
                "primitive diamond and generic-constructor specialization");
        assertTrue(linkages.contains("ironwood.Utility.identity$specialization$M0_int"),
                "primitive callable inference specialization");
        assertTrue(linkages.stream().anyMatch(linkage -> linkage.startsWith(
                                "ironwood.Utility.select")
                        && linkage.endsWith("$specialization$M0_int")),
                "primitive generic overload specialization: " + linkages);
    }

