    private void diamondInferenceRejectsUnsafeForms() {
        assertDiagnostic("""
                class Box<T> { Box() { } }
                class Main { public static int main(String[] args) {
                    Object value = new Box<>();
                    return value == null ? 0 : 1;
                } }
                """, "cannot infer diamond type argument T without non-null constructor or expected-type evidence");
        assertDiagnostic("""
                class Box<T> { Box(T value) { } }
                class Main { public static int main(String[] args) {
                    Box<String> value = new Box<>(new Object());
                    return value == null ? 0 : 1;
                } }
                """, "does not satisfy invariant inference ironwood.lang.String");
        assertDiagnostic("""
                class Box<T> { Box(T value) { } }
                class Main { public static int main(String[] args) {
                    Object value = new Box<>(null);
                    return value == null ? 0 : 1;
                } }
                """, "cannot infer diamond type argument T without non-null constructor or expected-type evidence");
        CompilationArtifact innerDiamond = compile("""
                class Outer<T> {
                    class Inner<U> { Inner(U value) { } }
                }
                class Main { public static int main(String[] args) {
                    Outer<String> outer = new Outer<String>();
                    Outer<String>.Inner<String> value = outer.new Inner<>("value");
                    return value == null ? 0 : 1;
                } }
                """);
        assertTrue(innerDiamond.successful(), messages(innerDiamond));
        CompilationArtifact anonymousDiamond = compile("""
                class Base<T> { Base(T value) { } }
                class Main { public static int main(String[] args) {
                    Base<String> value = new Base<>("value") { };
                    return value == null ? 0 : 1;
                } }
                """);
        assertTrue(anonymousDiamond.successful(), messages(anonymousDiamond));
        CompilationArtifact privateHelper = compile("""
                class Base<T> { Base(T value) { } int value() { return 0; } }
                class Main { public static int main(String[] args) {
                    Base<String> value = new Base<>("value") {
                        private int helper() { return 42; }
                        @Override int value() { return helper(); }
                    };
                    return value.value();
                } }
                """);
        assertTrue(privateHelper.successful(), messages(privateHelper));
        assertDiagnostic("""
                class Base<T> { Base(T value) { } }
                class Main { public static int main(String[] args) {
                    Base<String> value = new Base<>("value") {
                        int newMethod() { return 1; }
                    };
                    return value == null ? 0 : 1;
                } }
                """, "cannot declare non-private method 'newMethod()' unless it overrides");
    }

    private void localAndAnonymousClassesLowerToTypedIr() {
        CompilationArtifact artifact = compile("""
                class Box<T> {
                    T value;
                    Box(T value) { this.value = value; }
                    T value() { return value; }
                }
                interface Value<T> { T value(); }
                class Main {
                    static <T> T identity(T input) {
                        class Local { T value() { return input; } }
                        Local local = new Local();
                        Value<T> anonymous = new Value<T>() {
                            @Override public T value() { return local.value(); }
                        };
                        return anonymous.value();
                    }
                    public static int main(String[] args) {
                        Box<String> value = new Box<>(identity("value")) { };
                        return value.value().length();
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        List<IrAllocateInstruction> anonymousAllocations = artifact.program().orElseThrow()
                .functions().stream().flatMap(function -> function.blocks().stream())
                .flatMap(block -> block.instructions().stream())
                .filter(IrAllocateInstruction.class::isInstance)
                .map(IrAllocateInstruction.class::cast)
                .filter(allocation -> allocation.className().contains("$"))
                .toList();
        assertTrue(anonymousAllocations.stream().anyMatch(allocation ->
                        allocation.result().type().typeArguments().stream()
                                .anyMatch(argument -> argument.equals(
                                        IrType.reference("ironwood.lang.String")))),
                "anonymous diamond allocation did not retain inferred String exact type: "
                        + anonymousAllocations);
        assertTrue(artifact.program().orElseThrow().classes().stream()
                        .filter(type -> type.name().contains("$"))
                        .flatMap(type -> type.fields().stream())
                        .anyMatch(field -> field.name().startsWith("<capture:")),
                "local and anonymous classes did not expose deterministic hidden capture fields");

        assertDiagnostic("""
                class Item { }
                class Main { public static int main(String[] args) {
                    Item item = new Item();
                    class Holder { Item value() { return item; } }
                    Holder holder = new Holder();
                    free item;
                    return holder == null ? 1 : 0;
                } }
                """, "captured variable");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    int value = 1;
                    class Local { int value() { return value; } }
                    value = 2;
                    return new Local().value();
                } }
                """, "effectively final");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    int value = 1;
                    class Local { int value() { return value; } }
                    value += 2;
                    return 0;
                } }
                """, "effectively final");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    int value = 1;
                    class Local { int value() { return value; } }
                    ++value;
                    return 0;
                } }
                """, "effectively final");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    int value = 1;
                    class Local { int value() { return value; } }
                    value++;
                    return 0;
                } }
                """, "effectively final");
        assertDiagnostic("""
                class Main {
                    static int capture(int value) {
                        class Local { int value() { return value; } }
                        value = 2;
                        return 0;
                    }
                    public static int main(String[] args) { return capture(1); }
                }
                """, "effectively final");
        assertDiagnostic("""
                class Box<T> { Box() { } }
                class Main { public static int main(String[] args) {
                    Box<String> value = new Box<>() { T illegal; };
                    return value == null ? 0 : 1;
                } }
                """, "unknown class type 'T'");

        CompilationArtifact distinctOwners = compile("""
                class Token { int amount() { return 7; } }
                class First<T> {
                    class Inner<U> {
                        T outer;
                        U inner;
                        Inner(T outer, U inner) { this.outer = outer; this.inner = inner; }
                        T outer() { return outer; }
                        U inner() { return inner; }
                    }
                }
                class Second<T> { class Inner<U> { Inner(T outer, U inner) { } } }
                class Main {
                    static First<String> choose(First<String> value) { return value; }
                    public static int main(String[] args) {
                        First<String> first = new First<String>();
                        Second<Token> second = new Second<Token>();
                        First<String>.Inner<Token> value = choose(first).new Inner<Token>(
                                "owner", new Token()) {
                            int result() { return outer().length() + inner().amount(); }
                        };
                        return value == null || second == null ? 0 : 1;
                    }
                }
                """);
        assertTrue(distinctOwners.successful(), messages(distinctOwners));

        CompilationArtifact wildcardOwner = compile("""
                class Base { }
                class Child extends Base { }
                class Outer<T> {
                    T value;
                    Outer(T value) { this.value = value; }
                    class Inner { T value() { return Outer.this.value; } }
                }
                class Main {
                    static Outer<? extends Base> choose() {
                        return new Outer<Child>(new Child());
                    }
                    public static int main(String[] args) {
                        Base value = choose().new Inner() { }.value();
                        return value == null ? 0 : 42;
                    }
                }
                """);
        assertTrue(wildcardOwner.successful(), messages(wildcardOwner));

        CompilationArtifact dependentBound = compile("""
                class Base { }
                class Child extends Base { }
                class Outer<T> {
                    class Inner<U extends T> { Inner(U value) { } }
                }
                class Main { public static int main(String[] args) {
                    Outer<Base> outer = new Outer<Base>();
                    Outer<Base>.Inner<Child> value = outer.new Inner<Child>(new Child()) { };
                    return value == null ? 0 : 42;
                } }
                """);
        assertTrue(dependentBound.successful(), messages(dependentBound));
        assertDiagnostic("""
                class Base { }
                class Child extends Base { }
                class Other { }
                class Outer<T> { class Inner<U extends T> { Inner(U value) { } } }
                class Main { public static int main(String[] args) {
                    Outer<Base> outer = new Outer<Base>();
                    Outer<Base>.Inner<Other> value = outer.new Inner<Other>(new Other()) { };
                    return value == null ? 0 : 42;
                } }
                """, "does not satisfy bound Base");
        assertDiagnostic("""
                interface Required { int value(); }
                class Main { public static int main(String[] args) {
                    Required value = new Required() { };
                    return value == null ? 0 : 1;
                } }
                """, "does not implement interface method");

        CompilationArtifact inaccessible = compileSources(
                SourceFile.of("src/library/Base.iron", """
                        package library;
                        public class Base { private Base() { } }
                        """),
                SourceFile.of("src/app/Main.iron", """
                        package app;
                        import library.Base;
                        class Main { public static int main(String[] args) {
                            Base value = new Base() { };
                            return value == null ? 0 : 1;
                        } }
                        """));
        assertTrue(!inaccessible.successful(), "private superclass constructor was accepted");
        assertContains(messages(inaccessible), "has no accessible constructor",
                "anonymous private-superconstructor diagnostic");

        CompilationArtifact sameNestPrivate = compile("""
                class Main {
                    private class Base { private Base(int value) { } }
                    int run() {
                        Base value = new Base(42) { };
                        return value == null ? 0 : 42;
                    }
                    public static int main(String[] args) { return new Main().run(); }
                }
                """);
        assertTrue(sameNestPrivate.successful(), messages(sameNestPrivate));

        CompilationArtifact qualifiedOrder = compile("""
                class Outer {
                    class Inner { Inner(int value) { } }
                }
                class Main {
                    static Outer qualifier() { return new Outer(); }
                    static int argument() { return 42; }
                    public static int main(String[] args) {
                        Outer.Inner value = qualifier().new Inner(argument()) { };
                        return value == null ? 0 : 42;
                    }
                }
                """);
        assertTrue(qualifiedOrder.successful(), messages(qualifiedOrder));
        List<Object> mainInstructions = qualifiedOrder.program().orElseThrow().functions().stream()
                .filter(function -> function.linkageName().contains("Main.main"))
                .flatMap(function -> function.blocks().stream())
                .flatMap(block -> block.instructions().stream())
                .map(instruction -> (Object) instruction).toList();
        int qualifierCall = indexOfCall(mainInstructions, "Main.qualifier");
        int nullCheck = indexOfInstruction(mainInstructions, IrNullCheckInstruction.class);
        int argumentCall = indexOfCall(mainInstructions, "Main.argument");
        assertEquals(1L, mainInstructions.stream().filter(IrCallInstruction.class::isInstance)
                        .map(IrCallInstruction.class::cast)
                        .filter(call -> call.targetLinkageName().contains("Main.qualifier")).count(),
                "qualified anonymous primary evaluation count");
        assertTrue(qualifierCall >= 0 && nullCheck > qualifierCall && argumentCall > nullCheck,
                "qualified creation order must be primary, null check, then arguments: "
                        + mainInstructions);
    }

    private static int indexOfCall(List<Object> instructions, String linkageFragment) {
        for (int index = 0; index < instructions.size(); index++) {
            Object instruction = instructions.get(index);
            if (instruction instanceof IrCallInstruction call
                    && call.targetLinkageName().contains(linkageFragment)) {
                return index;
            }
        }
        return -1;
    }

    private static int indexOfInstruction(List<Object> instructions, Class<?> type) {
        for (int index = 0; index < instructions.size(); index++) {
            if (type.isInstance(instructions.get(index))) {
                return index;
            }
        }
        return -1;
    }

    private void constructedLexicalTypesPropagateCaptures() {
        CompilationArtifact artifact = compile("""
                class Main {
                    static int value() {
                        final int captured = 42;
                        final int unrelated = 7;
                        class Local {
                            class Inner { int value() { return captured; } }
                            class Implementation {
                                int value() { return new Inner().value(); }
                            }
                            int value() { return new Implementation().value(); }
                        }
                        class Unrelated { int value() { return 1; } }
                        Unrelated unused = new Unrelated();
                        return new Local().value() + unrelated - 7;
                    }
                    public static int main(String[] args) { return value(); }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        IrProgram program = artifact.program().orElseThrow();
        IrClass implementation = program.classes().stream()
                .filter(type -> type.name().endsWith("$Implementation"))
                .findFirst().orElseThrow();
        assertTrue(implementation.fields().stream()
                        .anyMatch(field -> field.name().endsWith(":captured>")),
                "constructing member class omitted the transitive capture field");
        assertTrue(program.functions().stream()
                        .filter(function -> function.ownerClass().equals(implementation.name()))
                        .filter(function -> function.linkageName().endsWith(".<init>"))
                        .flatMap(function -> function.parameters().stream())
                        .anyMatch(parameter -> parameter.name().endsWith(":captured>")),
                "constructing member constructor omitted the transitive capture ABI operand");
        IrClass unrelated = program.classes().stream()
                .filter(type -> type.name().endsWith("Unrelated"))
                .findFirst().orElseThrow();
        assertTrue(unrelated.fields().stream()
                        .noneMatch(field -> field.name().startsWith("<capture:")),
                "unrelated lexical class overcaptured an unused method local");
    }

    private void genericCallsPreserveSafeFreeSummaries() {
        CompilationArtifact accepted = compile("""
                class Helper<T> { void observe(T value) { } }
                class Item { }
                class Main { public static int main(String[] args) {
                    Helper<Item> helper = new Helper<Item>();
                    Item item = new Item();
                    helper.observe(item);
                    free item;
                    return 0;
                } }
                """);
        assertTrue(accepted.successful(), messages(accepted));
        assertTrue(accepted.program().orElseThrow().functions().stream()
                        .flatMap(function -> function.blocks().stream())
                        .flatMap(block -> block.instructions().stream())
                        .anyMatch(IrFreeInstruction.class::isInstance),
                "generic nonescaping call did not retain safe-free proof");
        CompilationArtifact ignoredIdentity = compile("""
                class Helper<T> { T identity(T value) { return value; } }
                class Item { }
                class Main { public static int main(String[] args) {
                    Helper<Item> helper = new Helper<Item>();
                    Item item = new Item();
                    helper.identity(item);
                    free item;
                    return 0;
                } }
                """);
        assertTrue(ignoredIdentity.successful(), messages(ignoredIdentity));
        assertTrue(ignoredIdentity.program().orElseThrow().functions().stream()
                        .flatMap(function -> function.blocks().stream())
                        .flatMap(block -> block.instructions().stream())
                        .anyMatch(IrFreeInstruction.class::isInstance),
                "ignored identity result did not retain safe-free proof");
        assertDiagnostic("""
                class Helper<T> { T publish(T value) { return value; } }
                class Item { }
                class Main { public static int main(String[] args) {
                    Helper<Item> helper = new Helper<Item>();
                    Item item = new Item();
                    Item alias = helper.publish(item);
                    free item;
                    return 0;
                } }
                """, "allocation may still be observed through local 'alias'");
    }

