    private void remainingStatementSemanticsAreChecked() {
        CompilationArtifact accepted = compile("""
                class Main {
                    static int inspect(int[] values) {
                        int total = 0;
                        outer:
                        do {
                            for (final int value : values) {
                                final class Capture {
                                    int read() { return value; }
                                }
                                Capture capture = new Capture();
                                try {
                                    total += capture.read();
                                    if (value == 1) { continue outer; }
                                    break outer;
                                } finally {
                                    total++;
                                }
                            }
                            break outer;
                        } while (false);
                        section: {
                            try { break section; }
                            finally { total++; }
                        }
                        ;
                        return total;
                    }
                    public static int main(String[] args) {
                        int[] values = new int[1];
                        values[0] = 1;
                        return inspect(values);
                    }
                }
                """);
        assertTrue(accepted.successful(), messages(accepted));

        CompilationArtifact cleanupAssignment = compile("""
                class AssignedInCleanup {
                    final int value;
                    AssignedInCleanup() {
                        exit: {
                            try { break exit; }
                            finally { value = 42; }
                        }
                    }
                }
                class AssignedInSwitchCleanup {
                    final int value;
                    AssignedInSwitchCleanup(int input) {
                        switch (input) {
                            default:
                                try { break; }
                                finally { value = 42; }
                        }
                    }
                }
                class Main { public static int main(String[] args) { return 0; } }
                """);
        assertTrue(cleanupAssignment.successful(), messages(cleanupAssignment));

        assertDiagnostic("""
                class Main { static void work() { do { } while (1); } }
                """, "do-while condition must have type boolean");
        assertDiagnostic("""
                class Main { static void work() { for (int value : 1) { } } }
                """, "enhanced-for expression must have an array type or implement "
                        + "ironwood.lang.Iterable, not int");
        assertDiagnostic("""
                class Main { static void work() { for (int value : work()) { } } }
                """, "enhanced-for expression must have an array type or implement "
                        + "ironwood.lang.Iterable, not void");
        assertDiagnostic("""
                class Main { static void work() { for (Object value : null) { } } }
                """, "enhanced-for expression must have an array type or implement "
                        + "ironwood.lang.Iterable, not null");
        assertDiagnostic("""
                class Main { static void work(boolean[] values) {
                    for (int value : values) { }
                } }
                """, "cannot assign enhanced-for element of type boolean to int variable 'value'");
        assertDiagnostic("""
                class Main { static void work(int[] values) {
                    for (final int value : values) { value = 2; }
                } }
                """, "final variable 'value'");
        assertDiagnostic("""
                class Main { static int work(int[] values) {
                    for (int value : values) { }
                    return value;
                } }
                """, "unknown local variable 'value'");
        assertDiagnostic("""
                class Main { static void work() { break missing; } }
                """, "unknown statement label 'missing'");
        assertDiagnostic("""
                class Main { static void work() { continue missing; } }
                """, "unknown statement label 'missing'");
        assertDiagnostic("""
                class Main { static void work() { section: { continue section; } } }
                """, "continue label 'section' does not denote a loop");
        assertDiagnostic("""
                class Main { static void work() {
                    outer: while (true) { outer: while (true) { break outer; } }
                } }
                """, "duplicate active statement label 'outer'");
        assertDiagnostic("""
                class ReassignedInCleanup {
                    final int value;
                    ReassignedInCleanup() {
                        exit: {
                            try { value = 1; break exit; }
                            finally { value = 2; }
                        }
                    }
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "final field 'value' may only be assigned once");
    }

    private void classicSwitchSemanticsAreChecked() {
        CompilationArtifact accepted = compile("""
                class FinalChoice {
                    final int value;
                    FinalChoice(int input) {
                        switch (input) {
                            case 0: value = 1; break;
                            default: value = 2; break;
                        }
                    }
                }
                class StaticChoice {
                    static final int VALUE;
                    static {
                        switch (1) {
                            case 1: VALUE = 40; break;
                            default: VALUE = 0; break;
                        }
                    }
                }
                class Main {
                    static final int TWO = 1 + 1;
                    static int exhaustive(char value) {
                        final int three = TWO + 1;
                        switch (value) {
                            case 0: return 0;
                            case TWO: return 2;
                            case three: return 3;
                            case (char) 65535: return 4;
                            default: return 42;
                        }
                    }
                    static int transfers(int input) {
                        int result = 0;
                        for (int index = 0; index < 3; index++) {
                            switch (input + index) {
                                case 1: continue;
                                case 2: break;
                                default: result++;
                            }
                            result += 2;
                        }
                        return result;
                    }
                    static int localType(int input) {
                        final int captured = 42;
                        switch (input) {
                            case 0:
                                class Local {
                                    int value() { return captured; }
                                }
                                Local local = new Local();
                                return local.value();
                            default: return 0;
                        }
                    }
                    public static int main(String[] args) {
                        FinalChoice choice = new FinalChoice(0);
                        return exhaustive('x') + transfers(0) + choice.value
                                + StaticChoice.VALUE + localType(0) - 87;
                    }
                }
                """);
        assertTrue(accepted.successful(), messages(accepted));

        CompilationArtifact stackedDefault = compile("""
                class Main {
                    static int value(int input) {
                        switch (input) {
                            case 1:
                            default:
                                return 42;
                        }
                    }
                    public static int main(String[] args) { return value(1); }
                }
                """);
        assertTrue(stackedDefault.successful(), messages(stackedDefault));

        CompilationArtifact caseLocalFree = compile("""
                class Box { }
                class Main {
                    static void release(int input) {
                        switch (input) {
                            case 0: {
                                Box box = new Box();
                                free box;
                                break;
                            }
                            default: break;
                        }
                    }
                    public static int main(String[] args) { release(0); return 0; }
                }
                """);
        assertTrue(caseLocalFree.successful(), messages(caseLocalFree));

        for (String selector : List.of("true", "1L", "1.0", "null")) {
            assertDiagnostic("class Main { public static int main(String[] args) { "
                            + "switch (" + selector + ") { default: return 0; } } }",
                    "switch selector must have type byte, short, char, or int");
        }
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    int value = 1; switch (value) { case value: return 1; default: return 0; }
                } }
                """, "case label must be a compile-time integral constant expression");
        assertDiagnostic("""
                class Main { static int value() { return 1; }
                    public static int main(String[] args) {
                        switch (1) { case value(): return 1; default: return 0; }
                    }
                }
                """, "case label must be a compile-time integral constant expression");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    byte value = 1;
                    switch (value) { case 128: return 1; default: return 0; }
                } }
                """, "is not compatible with switch selector type byte");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    switch (1) { case 1: return 1; case (byte) 1: return 2; default: return 0; }
                } }
                """, "duplicate case label value 1");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    switch (1) { default: return 1; default: return 2; }
                } }
                """, "duplicate default label in switch statement");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    switch (1) {
                        case 0: int local = 1;
                        case 1: return local;
                        default: return 0;
                    }
                } }
                """, "might not have been initialized on every path to this switch label");
        assertDiagnostic("""
                class Main { public static int main(String[] args) {
                    switch (1) { case 1: continue; default: return 0; }
                } }
                """, "continue statement is only valid inside a loop");
        assertDiagnostic("""
                class Main {
                    static int incomplete(int value) {
                        switch (value) { case 1: return 1; }
                    }
                    public static int main(String[] args) { return incomplete(1); }
                }
                """, "does not return a value on every path");
        CompilationArtifact acrossSwitch = compile("""
                class Box { }
                class Main { public static int main(String[] args) {
                    Box box = new Box();
                    switch (1) { case 1: break; default: break; }
                    free box;
                    return 0;
                } }
                """);
        assertTrue(acrossSwitch.successful(), messages(acrossSwitch));
    }

    private void modernSwitchSemanticsAreChecked() {
        CompilationArtifact accepted = compile("""
                enum Mode { START, STOP }
                class Choice {
                    final int value;
                    final int cleanup;
                    Choice() {
                        value = switch (0) {
                            default -> {
                                try { yield 40; }
                                finally { cleanup = 2; }
                            }
                        };
                    }
                }
                class Main {
                    static int integral(int value) {
                        return switch (value) {
                            case 0, 1 -> 1;
                            default -> {
                                int adjusted = value + 40;
                                yield adjusted;
                            }
                        };
                    }
                    static String text(String command) {
                        return switch (command) {
                            case null -> "missing";
                            case "start", "resume" -> "active";
                            default -> command;
                        };
                    }
                    static int colonText(String command) {
                        int result = -1;
                        switch (command) {
                            case null: result = 0; break;
                            case "start", "resume": result = 42; break;
                            default: result = 1;
                        }
                        return result;
                    }
                    static int alwaysThrows(int input) {
                        return switch (input) {
                            default -> throw new IllegalArgumentException();
                        };
                    }
                    static long numeric(int input) {
                        return switch (input) { case 0 -> 1; default -> 2L; };
                    }
                    public static int main(String[] args) {
                        Choice choice = new Choice();
                        byte narrowed = switch (1) { case 1 -> 1; default -> 2; };
                        return integral(2) + choice.value + choice.cleanup
                                + colonText("resume") + narrowed + (int) numeric(0) - 86;
                    }
                }
                """);
        assertTrue(accepted.successful(), messages(accepted));

        assertDiagnostic("""
                class Main { static int value(int input) {
                    return switch (input) { case 1 -> 1; };
                } }
                """, "switch expression must declare a default rule");
        assertDiagnostic("""
                enum State { A, B }
                class Main { static int value(State state) {
                    return switch (state) { case A -> 1; };
                } }
                """, "must cover every enum constant or declare default");
        assertDiagnostic("""
                class Main { static int value(int input) {
                    return switch (input) { case null -> 0; default -> 1; };
                } }
                """, "case null requires an enum or ironwood.lang.String selector");
        assertDiagnostic("""
                class Main { static int value(String input) {
                    return switch (input) {
                        case "same" -> 1; case "sa" + "me" -> 2; default -> 0;
                    };
                } }
                """, "duplicate String case label value 'same'");
        assertDiagnostic("""
                class Constants { private static final String HIDDEN = "hidden"; }
                class Main { static int value(String input) {
                    return switch (input) {
                        case Constants.HIDDEN -> 1; default -> 0;
                    };
                } }
                """, "field 'HIDDEN' is private");
        assertDiagnostic("""
                class Main { static int value(int input) {
                    return switch (input) { case 0 -> 1; default -> null; };
                } }
                """, "switch expression result branches have incompatible types");
        assertDiagnostic("""
                class Main { static int value() { yield 1; return 0; } }
                """, "yield is only valid inside a switch expression");
        assertDiagnostic("""
                class Main { static int value(int input) {
                    while (true) {
                        int result = switch (input) { default: break; };
                    }
                } }
                """, "unlabeled break is not permitted inside a switch expression");
        assertDiagnostic("""
                class Main { static void value(int input) {
                    switch (input) { case 0 -> 42; default -> { } }
                } }
                """, "expression statement must be an assignment");
        assertDiagnostic("""
                class Box { }
                class Main { static void release(int input) {
                    Box box = switch (input) {
                        case 0 -> new Box();
                        default -> new Box();
                    };
                    free box;
                }
                    public static int main(String[] args) { release(0); return 0; }
                }
                """, "value is not a known allocation created by new in this method");
    }

    private void enumSemanticsAreChecked() throws Exception {
        CompilationArtifact accepted = compile("""
                interface Tagged { int tag(); }
                class Box<T> { T value; Box(T value) { this.value = value; } }
                enum State implements Tagged {
                    READY(10), RUNNING(20), DONE(30);
                    private final int code;
                    State(int code) { this.code = code; }
                    @Override public int tag() { return code; }
                    @Override public String toString() { return name(); }
                }
                class Holder {
                    private enum Hidden { ONLY }
                    static int hiddenCount() { return Hidden.valueCount(); }
                }
                class Main {
                    static int classify(State value) {
                        switch (value) {
                            case READY: return 1;
                            case RUNNING:
                            case DONE: return value.tag();
                            default: return 0;
                        }
                    }
                    public static int main(String[] args) {
                        State[] array = new State[1];
                        array[0] = State.valueOf("RUNNING");
                        Box<State> box = new Box<State>(array[0]);
                        Object object = box.value;
                        State restored = (State) object;
                        if (!(restored instanceof Tagged) || State.valueAt(1) != restored
                                || State.valueCount() != 3 || restored.ordinal() != 1
                                || !restored.name().equals("RUNNING")) { return 1; }
                        try { State.valueOf(null); }
                        catch (IllegalArgumentException expected) {
                            return classify(restored) + Holder.hiddenCount() + 21;
                        }
                        return 0;
                    }
                }
                """);
        assertTrue(accepted.successful(), messages(accepted));

        NativeResult values = compileAndRunNative("Main.iron", """
                enum State { READY, RUNNING, DONE }
                class Main {
                    public static int main(String[] args) {
                        long baseline = System.liveAllocationCount();
                        State[] first = State.values();
                        State[] second = State.values();
                        boolean valid = first != second && first.length == 3 && second.length == 3
                                && first[0] == State.READY && first[1] == State.RUNNING
                                && first[2] == State.DONE && second[0] == State.READY;
                        first[0] = State.DONE;
                        valid = valid && second[0] == State.READY;
                        free second;
                        free first;
                        return valid && System.liveAllocationCount() == baseline ? 42 : 1;
                    }
                }
                """, "Main", "-O3");
        assertEquals(42, values.exit(), "enum values native exit");
        assertEquals("", values.stdout(), "enum values native output");
        assertEquals("", values.stderr(), "enum values native error");

        assertDiagnostic("""
                enum State { READY }
                class Main { public static int main(String[] args) {
                    State value = new State(); return 0;
                } }
                """, "cannot create an instance of enum 'State'");
        assertDiagnostic("""
                enum State { READY }
                class Child extends State { }
                class Main { public static int main(String[] args) { return 0; } }
                """, "cannot extend final class 'State'");
        assertDiagnostic("""
                enum State { READY; public State() { } }
                class Main { public static int main(String[] args) { return 0; } }
                """, "enum constructors are implicitly private");
        assertDiagnostic("""
                enum State { READY; protected State() { } }
                class Main { public static int main(String[] args) { return 0; } }
                """, "enum constructors are implicitly private");
        assertDiagnostic("""
                protected enum State { READY }
                class Main { public static int main(String[] args) { return 0; } }
                """, "top-level enum 'State' may only be public or package-private");
        assertDiagnostic("""
                enum State { READY; State() { super(); } }
                class Main { public static int main(String[] args) { return 0; } }
                """, "enum constructors cannot invoke super(...) explicitly");
        assertDiagnostic("""
                enum State { READY; <T> State() { } }
                class Main { public static int main(String[] args) { return 0; } }
                """, "enum constructors cannot declare type parameters");
        assertDiagnostic("""
                enum State { READY, READY }
                class Main { public static int main(String[] args) { return 0; } }
                """, "duplicate enum constant 'READY'");
        assertDiagnostic("""
                enum State { READY }
                class Main { public static int main(String[] args) {
                    State.READY = null; return 0;
                } }
                """, "cannot assign to or update final field 'READY'");
        assertDiagnostic("""
                enum State { READY; public static State[] values() { return new State[] {READY}; } }
                class Main { public static int main(String[] args) { return 0; } }
                """, "duplicate method 'values()'");
        assertDiagnostic("""
                enum State { READY, DONE }
                class Main { public static int main(String[] args) {
                    switch (State.READY) { case State.READY: return 1; default: return 0; }
                } }
                """, "enum case label must be an unqualified constant of 'State'");
        assertDiagnostic("""
                enum State { READY, DONE }
                class Main { public static int main(String[] args) {
                    switch (State.READY) { case READY: return 1; case READY: return 2; default: return 0; }
                } }
                """, "duplicate case label value 0");
        assertDiagnostic("""
                enum State { READY }
                enum Other { OTHER }
                class Main { public static int main(String[] args) {
                    switch (State.READY) { case OTHER: return 1; default: return 0; }
                } }
                """, "enum case label must be an unqualified constant of 'State'");
        assertDiagnostic("""
                enum State { READY }
                class Main { public static int main(String[] args) {
                    free State.READY; return 0;
                } }
                """, "free target must be a local variable created by new in this method");
        assertDiagnostic("""
                class Checked extends Exception { }
                enum State { READY; State() throws Checked { } }
                class Main { public static int main(String[] args) { return State.valueCount(); } }
                """, "unreported checked exception Checked from call to 'State'");
    }

    private void enumConstantBodiesAreChecked() {
        CompilationArtifact accepted = compile("""
                interface Operation { int apply(int left, int right); }
                enum Arithmetic implements Operation {
                    ADD(1) {
                        private final int adjustment = 1;
                        private final int initialized;
                        { initialized = seed() + adjustment; }
                        @Override public int apply(int left, int right) {
                            return left + right + initialized - 2;
                        }
                    },
                    SUBTRACT(2) {
                        @Override public int apply(int left, int right) {
                            return left - right;
                        }
                    };
                    private final int seed;
                    Arithmetic(int seed) { this.seed = seed; }
                    private int seed() { return seed; }
                    @Override public abstract int apply(int left, int right);
                }
                class Main {
                    public static int main(String[] args) {
                        Operation operation = Arithmetic.ADD;
                        return operation.apply(20, 22);
                    }
                }
                """);
        assertTrue(accepted.successful(), messages(accepted));

        assertDiagnostic("""
                interface Work { int run(); }
                enum Incomplete implements Work {
                    READY { public int run() { return 1; } },
                    BROKEN { }
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "does not implement interface method 'run()'");
        assertDiagnostic("""
                interface Work { int run(); }
                enum Incomplete implements Work {
                    READY { public int run() { return 1; } }, BROKEN
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "class 'Incomplete' does not implement interface method 'run()'");
        assertDiagnostic("""
                enum Incomplete {
                    READY { public int run() { return 1; } }, BROKEN;
                    public abstract int run();
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "abstract method 'run' may only be declared in an abstract class");
        assertDiagnostic("""
                enum HiddenMember {
                    VALUE { int bodyOnly() { return 42; } }
                }
                class Main {
                    public static int main(String[] args) {
                        return HiddenMember.VALUE.bodyOnly();
                    }
                }
                """, "type 'HiddenMember' has no method 'bodyOnly'");
        assertDiagnostic("""
                enum FinalMember {
                    VALUE { public String name() { return "changed"; } }
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "cannot override final method inherited from 'FinalMember'");
        assertDiagnostic("""
                enum Immortal { VALUE { int code() { return 1; } } }
                class Main { public static int main(String[] args) {
                    Immortal value = Immortal.VALUE;
                    free value;
                    return 0;
                } }
                """, "value is not a known allocation created by new in this method");
    }

