    private void packagesCompileAcrossFiles() {
        CompilationArtifact artifact = compileSources(
                SourceFile.of("src/demo/lib/Answer.iron", """
                        package demo.lib;
                        public class Answer {
                            public static int value() { return 42; }
                        }
                        """),
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import demo.lib.Answer;
                        public class Main {
                            public static int main(String[] args) { return Answer.value(); }
                        }
                        """));
        assertTrue(artifact.successful(), messages(artifact));
        assertContains(artifact.llvmIr().orElseThrow(), "ironwood.demo.lib.Answer.value",
                "qualified static linkage");
        assertTrue(artifact.program().orElseThrow().classes().stream()
                        .anyMatch(type -> type.name().equals("demo.app.Main")),
                "qualified entry class missing from IR");

        CompilationArtifact importedTypeWins = compileSources(
                SourceFile.of("src/other/Value.iron", """
                        package other;
                        public class Value { public static int read() { return 42; } }
                        """),
                SourceFile.of("src/demo/app/Value.iron", """
                        package demo.app;
                        public class Value { public static int read() { return 1; } }
                        """),
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import other.Value;
                        public class Main { public static int main(String[] args) { return Value.read(); } }
                        """));
        assertTrue(importedTypeWins.successful(), messages(importedTypeWins));
        assertContains(importedTypeWins.llvmIr().orElseThrow(), "call i32 @\"ironwood.other.Value.read\"",
                "single-type import should take precedence over a same-package type");
    }

    private void staticImportSyntaxIsAccepted() {
        var parsed = parseOnly("""
                package demo.app;
                import static demo.lib.Constants.VALUE;
                import static demo.lib.Operations.*;
                class Main { }
                """);
        assertTrue(parsed.diagnostics().isEmpty(), parsed.diagnostics().toString());
        var imports = parsed.unit().orElseThrow().imports();
        assertEquals(2, imports.size(), "static import count");
        assertTrue(imports.getFirst().staticImport() && !imports.getFirst().wildcard(),
                "single-static import flags");
        assertEquals("demo.lib.Constants", imports.getFirst().ownerName(),
                "single-static owner");
        assertEquals("VALUE", imports.getFirst().importedMemberName(),
                "single-static member");
        assertTrue(imports.get(1).staticImport() && imports.get(1).wildcard(),
                "static-on-demand import flags");
        assertEquals("demo.lib.Operations", imports.get(1).ownerName(),
                "static-on-demand owner");
        assertDiagnostic("import static Value; class Main { }",
                "single-static import requires a type name followed by a member name");
    }

    private void staticImportsResolveMembers() {
        CompilationArtifact artifact = compileSources(
                SourceFile.of("src/demo/lib/Constants.iron", """
                        package demo.lib;
                        public class Constants {
                            public static final int BASE = 19;
                            public static int RUNTIME = initialize();
                            private static int initialize() { return 1; }
                            public static class Result {
                                private int value;
                                public Result(int value) { this.value = value; }
                                public int value() { return value; }
                            }
                        }
                        """),
                SourceFile.of("src/demo/lib/BaseOperations.iron", """
                        package demo.lib;
                        public class BaseOperations {
                            public static final int INHERITED = 0;
                            public static int inherited() { return 0; }
                            public static class InheritedResult {
                                public InheritedResult() { }
                                public int value() { return 0; }
                            }
                        }
                        """),
                SourceFile.of("src/demo/lib/Operations.iron", """
                        package demo.lib;
                        public class Operations extends BaseOperations {
                            public static int twice(int value) { return value * 2; }
                            public static long twice(long value) { return value * 3L; }
                            public static <T> T identity(T value) { return value; }
                        }
                        """),
                SourceFile.of("src/demo/lib/Other.iron", """
                        package demo.lib;
                        public class Other {
                            public static final int BASE = 100;
                            public static int twice(int value) { return 100; }
                            public static int bonus() { return 0; }
                            public static class Result { }
                        }
                        """),
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static demo.lib.Constants.BASE;
                        import static demo.lib.Constants.RUNTIME;
                        import static demo.lib.Constants.Result;
                        import static demo.lib.Operations.twice;
                        import static demo.lib.Operations.twice;
                        import static demo.lib.Operations.INHERITED;
                        import static demo.lib.Operations.inherited;
                        import static demo.lib.Operations.InheritedResult;
                        import static demo.lib.Operations.*;
                        import static demo.lib.Other.*;
                        public class Main {
                            static final int COMPILED = BASE + 1;
                            public static int main(String[] args) {
                                Result result = new Result(identity(twice(COMPILED)));
                                InheritedResult inheritedResult = new InheritedResult();
                                RUNTIME += 1;
                                return result.value() + RUNTIME + bonus() + INHERITED
                                        + inherited() + inheritedResult.value();
                            }
                        }
                        class Shadow {
                            static int twice(int value) { return value + 1; }
                            static int verify() {
                                int BASE = 41;
                                return twice(BASE);
                            }
                        }
                        """));
        assertTrue(artifact.successful(), messages(artifact));
        String llvm = artifact.llvmIr().orElseThrow();
        assertContains(llvm, "demo.lib.Operations.twice", "single-static method target");
        assertContains(llvm, "demo.lib.Operations.identity", "static-on-demand generic target");
        var compiled = artifact.program().orElseThrow().staticFields().stream()
                .filter(field -> field.ownerClass().equals("demo.app.Main")
                        && field.name().equals("COMPILED"))
                .findFirst().orElseThrow();
        assertTrue(compiled.compileTimeConstant(),
                "static-imported constant did not fold in a static initializer");
    }

    private void invalidStaticImportsAreDiagnosed() {
        SourceFile invalidOwner = SourceFile.of("src/demo/lib/Invalid.iron", """
                package demo.lib;
                public class Invalid {
                    public int value;
                    private static int hidden;
                }
                """);
        CompilationArtifact noStaticMember = compileSources(invalidOwner,
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static demo.lib.Invalid.value;
                        public class Main {
                            public static int main(String[] args) { return 0; }
                        }
                        """));
        assertContains(messages(noStaticMember),
                "type 'demo.lib.Invalid' has no static member named 'value'",
                "non-static member import diagnostic");

        CompilationArtifact inaccessible = compileSources(invalidOwner,
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static demo.lib.Invalid.hidden;
                        public class Main {
                            public static int main(String[] args) { return 0; }
                        }
                        """));
        assertContains(messages(inaccessible),
                "static member 'demo.lib.Invalid.hidden' is not accessible",
                "inaccessible static member import diagnostic");

        SourceFile left = SourceFile.of("src/left/Values.iron", """
                package left;
                public class Values {
                    public static int VALUE = 1;
                    public static int choose(int value) { return value; }
                    public static class Entry { }
                }
                """);
        SourceFile right = SourceFile.of("src/right/Values.iron", """
                package right;
                public class Values {
                    public static int VALUE = 2;
                    public static int choose(int value) { return value; }
                    public static class Entry { }
                }
                """);
        CompilationArtifact ambiguousField = compileSources(left, right,
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static left.Values.*;
                        import static right.Values.*;
                        public class Main {
                            public static int main(String[] args) { return VALUE; }
                        }
                        """));
        assertContains(messages(ambiguousField), "ambiguous statically imported field 'VALUE'",
                "static-on-demand field ambiguity");

        CompilationArtifact ambiguousMethod = compileSources(left, right,
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static left.Values.*;
                        import static right.Values.*;
                        public class Main {
                            public static int main(String[] args) { return choose(42); }
                        }
                        """));
        assertContains(messages(ambiguousMethod), "ambiguous method 'choose'",
                "static-on-demand method ambiguity");

        CompilationArtifact conflictingType = compileSources(left, right,
                SourceFile.of("src/demo/app/Main.iron", """
                        package demo.app;
                        import static left.Values.Entry;
                        import static right.Values.Entry;
                        public class Main {
                            public static int main(String[] args) { return 0; }
                        }
                        """));
        assertContains(messages(conflictingType),
                "single-static imports for member type 'Entry' conflict",
                "single-static member-type conflict");
    }

    private void publicTypesFollowFilenameRules() {
        CompilationArtifact mismatch = compileSources(SourceFile.of("src/demo/Wrong.iron", """
                package demo;
                public class Right { public static int main(String[] args) { return 0; } }
                """));
        assertTrue(!mismatch.successful(), "mismatched public filename unexpectedly compiled");
        assertContains(messages(mismatch), "must be declared in Right.iron", "public filename diagnostic");

        CompilationArtifact multiple = compileSources(SourceFile.of("src/demo/First.iron", """
                package demo;
                public class First { public static int main(String[] args) { return 0; } }
                public class Second { }
                """));
        assertTrue(!multiple.successful(), "two public top-level types unexpectedly compiled");
        assertContains(messages(multiple), "at most one public top-level type", "public type count diagnostic");

        CompilationArtifact importConflict = compileSources(
                SourceFile.of("src/other/First.iron", "package other; public class First { }"),
                SourceFile.of("src/demo/First.iron", """
                        package demo;
                        import other.First;
                        public class First { public static int main(String[] args) { return 0; } }
                        """));
        assertContains(messages(importConflict), "conflicts with a top-level type declared in this file",
                "single-type import/top-level declaration conflict");
    }

    private void crossPackageAccessIsEnforced() {
        SourceFile base = SourceFile.of("src/base/Base.iron", """
                package base;
                public class Base {
                    int packageValue;
                    protected int protectedValue;
                    public Base() { packageValue = 1; protectedValue = 42; }
                }
                """);
        SourceFile child = SourceFile.of("src/app/Child.iron", """
                package app;
                import base.Base;
                public class Child extends Base {
                    public int read() { return protectedValue; }
                }
                """);
        SourceFile main = SourceFile.of("src/app/Main.iron", """
                package app;
                public class Main {
                    public static int main(String[] args) { Child child = new Child(); return child.read(); }
                }
                """);
        assertTrue(compileSources(base, child, main).successful(), "protected subclass access was rejected");

        CompilationArtifact packageAccess = compileSources(base, SourceFile.of("src/app/Main.iron", """
                package app;
                import base.Base;
                public class Main {
                    public static int main(String[] args) { Base value = new Base(); return value.packageValue; }
                }
                """));
        assertContains(messages(packageAccess), "field 'packageValue' is not accessible",
                "cross-package field diagnostic");

        CompilationArtifact protectedReceiver = compileSources(base, SourceFile.of("src/app/Child.iron", """
                package app;
                import base.Base;
                public class Child extends Base {
                    public int read(Base other) { return other.protectedValue; }
                    public static int main(String[] args) { return 0; }
                }
                """));
        assertContains(messages(protectedReceiver), "field 'protectedValue' is not accessible",
                "protected receiver diagnostic");
    }

    private void ambiguousWildcardImportsAreRejected() {
        CompilationArtifact artifact = compileSources(
                SourceFile.of("src/left/Value.iron", "package left; public class Value { }"),
                SourceFile.of("src/right/Value.iron", "package right; public class Value { }"),
                SourceFile.of("src/app/Main.iron", """
                        package app;
                        import left.*;
                        import right.*;
                        public class Main {
                            public static int main(String[] args) { Value value = null; return 0; }
                        }
                        """));
        assertTrue(!artifact.successful(), "ambiguous wildcard imports unexpectedly compiled");
        assertContains(messages(artifact), "ambiguous type 'Value'", "wildcard ambiguity diagnostic");
    }

    private void instanceFieldInitializersAndBlankFinalsAreChecked() {
        CompilationArtifact valid = compile("""
                class Box {
                    int first = 3;
                    final int second;
                    final int third = first + 2;
                    Box(boolean choose) {
                        if (choose) { second = 4; } else { this.second = 5; }
                    }
                    Box() { this(true); }
                    int value() { return first + second + third; }
                }
                class Main {
                    public static int main(String[] args) { return new Box().value(); }
                }
                """);
        assertTrue(valid.successful(), messages(valid));
        assertDiagnostic("class Main { final int value; Main() { } public static int main(String[] args) { return 0; } }",
                "blank final field 'value' is not definitely assigned");
        assertDiagnostic("class Main { final int value; Main() { value = 1; value = 2; } public static int main(String[] args) { return 0; } }",
                "final field 'value' may only be assigned once");
        assertDiagnostic("class Main { final int value; Main(boolean set) { if (set) { value = 1; } } public static int main(String[] args) { return 0; } }",
                "blank final field 'value' is not definitely assigned");
        assertDiagnostic("class Main { final int value; Main() { while (true) { value = 1; break; } } public static int main(String[] args) { return 0; } }",
                "cannot be assigned in a loop");
        assertDiagnostic("class Main { final int value; Main() { int before = value; value = 1; } public static int main(String[] args) { return 0; } }",
                "blank final field 'value' might not have been initialized");
        assertDiagnostic("class Main { final int value = 1; Main() { value = 2; } public static int main(String[] args) { return 0; } }",
                "cannot assign to or update final field 'value'");
        assertDiagnostic("class Main { final boolean value; Main(boolean condition) { if (condition && (value = true)) { } } public static int main(String[] args) { return 0; } }",
                "blank final field 'value' is not definitely assigned");
        assertDiagnostic("class Main { final boolean value; Main(boolean condition) { if (condition || (value = true)) { } } public static int main(String[] args) { return 0; } }",
                "blank final field 'value' is not definitely assigned");
        assertDiagnostic("class Main { final int value; Main() { this(1); value = 2; } Main(int value) { this.value = value; } public static int main(String[] args) { return 0; } }",
                "final field 'value' may only be assigned once");

        CompilationArtifact abrupt = compile("""
                class Main {
                    final int value;
                    Main() { throw new RuntimeException(); }
                    public static int main(String[] args) { return 0; }
                }
                """);
        assertTrue(abrupt.successful(), messages(abrupt));
        CompilationArtifact assignedByFinally = compile("""
                class Main {
                    final int value;
                    Main() { try { return; } finally { value = 1; } }
                    public static int main(String[] args) { return 0; }
                }
                """);
        assertTrue(assignedByFinally.successful(), messages(assignedByFinally));
        CompilationArtifact caughtThenAssigned = compile("""
                class Main {
                    final int value;
                    Main() {
                        try { throw new RuntimeException(); }
                        catch (RuntimeException failure) { value = 1; }
                    }
                    public static int main(String[] args) { return 0; }
                }
                """);
        assertTrue(caughtThenAssigned.successful(), messages(caughtThenAssigned));
        CompilationArtifact throwingFinally = compile("""
                class Main {
                    final int value;
                    Main() { try { return; } finally { throw new RuntimeException(); } }
                    public static int main(String[] args) { return 0; }
                }
                """);
        assertTrue(throwingFinally.successful(), messages(throwingFinally));
        assertDiagnostic("""
                class Main {
                    final int value;
                    Main() { try { value = 1; } finally { value = 2; } }
                    public static int main(String[] args) { return 0; }
                }
                """, "final field 'value' may only be assigned once");
        assertDiagnostic("""
                class Main {
                    final int value;
                    Main() {
                        try { value = 1; throw new RuntimeException(); }
                        catch (RuntimeException failure) { value = 2; }
                    }
                    public static int main(String[] args) { return 0; }
                }
                """, "final field 'value' may only be assigned once");
        assertDiagnostic("""
                class Main {
                    final int value;
                    int produce() { return 1; }
                    Main() {
                        try { value = produce(); }
                        finally { int observed = value; }
                    }
                    public static int main(String[] args) { return 0; }
                }
                """, "blank final field 'value' might not have been initialized");
    }

    private void nestedTypesAndInitializersAreChecked() {
        CompilationArtifact valid = compile("""
                class Main {
                    private static int secret = 2;
                    private int value = 37;
                    { value = value + 2; }
                    private final int finalValue;
                    { finalValue = 1; }
                    Main() { value = value + finalValue; }
                    private int add(int input) { return value + input; }
                    interface Value { int value(); }
                    static class Nested implements Value {
                        @Override public int value() { return secret; }
                    }
                    class Inner {
                        int captured;
                        Inner() { this(Main.this.value); }
                        Inner(int captured) { this.captured = captured; }
                        int value() { value = value + secret; return add(captured - value); }
                    }
                    Inner make() { return new Inner(); }
                    public static int main(String[] args) {
                        Main outer = new Main();
                        Inner explicit = outer.new Inner(0);
                        Inner implicit = outer.make();
                        Value nested = new Nested();
                        return implicit.value() + nested.value();
                    }
                }
                """);
        assertTrue(valid.successful(), messages(valid));
        assertTrue(valid.program().orElseThrow().classes().stream()
                        .anyMatch(type -> type.name().equals("Main$Nested")),
                "static nested class missing from typed IR");
        var inner = valid.program().orElseThrow().classes().stream()
                .filter(type -> type.name().equals("Main$Inner")).findFirst().orElseThrow();
        assertTrue(inner.fields().stream().anyMatch(field -> field.name().equals("<enclosing>")),
                "member inner class missing hidden enclosing field");
        var innerConstructor = valid.program().orElseThrow().functions().stream()
                .filter(function -> function.ownerClass().equals("Main$Inner")
                        && function.sourceName().equals("Inner")
                        && function.parameters().size() == 2)
                .findFirst().orElseThrow();
        assertEquals(2, innerConstructor.parameters().size(),
                "no-argument inner constructor hidden ABI parameter count");

        assertDiagnostic("""
                class Main {
                    int value;
                    static class Nested { int read() { return value; } }
                    public static int main(String[] args) { return 0; }
                }
                """, "instance field 'value' cannot be referenced from this static or lexical context");
        assertDiagnostic("""
                class Main {
                    class Inner { }
                    public static int main(String[] args) { Inner value = new Inner(); return 0; }
                }
                """, "requires an enclosing instance of 'Main'");
        assertDiagnostic("""
                class Outer {
                    static class Nested { Outer invalid() { return Outer.this; } }
                    public static int main(String[] args) { return 0; }
                }
                """, "'Outer.this' is not available in this static or lexical context");
        assertDiagnostic("""
                class Outer { }
                class Other {
                    Outer invalid() { return Outer.this; }
                    public static int main(String[] args) { return 0; }
                }
                """, "'Outer.this' is not available in this static or lexical context");
        assertDiagnostic("""
                class Outer {
                    class Inner { }
                    public static int main(String[] args) {
                        Outer outer = new Outer();
                        Outer.Inner inner = outer.new Inner();
                        free outer;
                        return inner == null ? 0 : 1;
                    }
                }
                """, "allocation is retained as an enclosing instance");
        assertDiagnostic("""
                class Outer {
                    class Inner { }
                    public static int main(String[] args) {
                        Outer outer = new Outer();
                        Outer.Inner inner = outer.new Inner() { };
                        free outer;
                        return inner == null ? 0 : 1;
                    }
                }
                """, "allocation is retained as the anonymous superclass enclosing instance");
        assertDiagnostic("""
                class Main {
                    static class Nested { }
                    public static int main(String[] args) {
                        Main outer = new Main();
                        Nested value = outer.new Nested();
                        return 0;
                    }
                }
                """, "static nested class 'Main.Nested' cannot be created with an enclosing instance");
        assertDiagnostic("""
                class Main {
                    Main(int arg) { }
                    int value;
                    { value = arg; }
                    public static int main(String[] args) { return 0; }
                }
                """, "unknown local variable 'arg'");
        assertDiagnostic("""
                class Main {
                    int first = later;
                    int later = 1;
                    public static int main(String[] args) { return 0; }
                }
                """, "illegal forward reference to instance field 'later'");
        assertDiagnostic("""
                class Main {
                    { int observed = later; }
                    int later = 1;
                    public static int main(String[] args) { return 0; }
                }
                """, "illegal forward reference to instance field 'later'");
        CompilationArtifact qualifiedForward = compile("""
                class Main {
                    int first = this.later;
                    int later = 1;
                    public static int main(String[] args) { return new Main().first; }
                }
                """);
        assertTrue(qualifiedForward.successful(), messages(qualifiedForward));
        assertDiagnostic("""
                class Main {
                    { return; }
                    public static int main(String[] args) { return 0; }
                }
                """, "return is not permitted in an instance initializer");
        CompilationArtifact staticBlock = compile("""
                class Main {
                    static { int value = 1; }
                    public static int main(String[] args) { return 0; }
                }
                """);
        assertTrue(staticBlock.successful(), messages(staticBlock));

        assertDiagnostic("""
                interface Left { class Nested { } }
                interface Right { class Nested { } }
                class Main implements Left, Right {
                    Nested value;
                    public static int main(String[] args) { return 0; }
                }
                """, "ambiguous type 'Nested'");
        assertDiagnostic("""
                class Main {
                    static class Base { private static class Hidden { } }
                    static class Child extends Base { Hidden value; }
                    public static int main(String[] args) { return 0; }
                }
                """, "unknown class type 'Hidden'");
        assertDiagnostic("""
                class Main {
                    class Main { }
                    public static int main(String[] args) { return 0; }
                }
                """, "cannot have the same name as an enclosing type");

        CompilationArtifact inheritedInner = compile("""
                class Outer<T> {
                    class Inner<U> { U value; Inner(U value) { this.value = value; } }
                    static class Nested { }
                }
                class Child extends Outer<String> {
                    Inner<String> make() { return new Inner<String>("ok"); }
                    Child.Nested nested;
                }
                class Main {
                    public static int main(String[] args) {
                        Child child = new Child();
                        Child.Inner<String> value = child.make();
                        return value.value.equals("ok") ? 0 : 1;
                    }
                }
                """);
        assertTrue(inheritedInner.successful(), messages(inheritedInner));

        CompilationArtifact segmentedGenerics = compile("""
                class Outer<T> {
                    T seed;
                    Outer(T seed) { this.seed = seed; }
                    class Inner<U> {
                        U value;
                        Inner(U value) { this.value = value; }
                        T outerValue() { return seed; }
                    }
                    static class StaticPair<A, B> { }
                }
                class Child<A, B> extends Outer<B> {
                    Child(B seed) { super(seed); }
                }
                class Main {
                    public static int main(String[] args) {
                        Child<Object, String> child = new Child<Object, String>("owner");
                        Child<Object, String>.Inner<Object> value =
                                child.new Inner<Object>(new Object());
                        Outer.StaticPair<String, Object> pair =
                                new Outer.StaticPair<String, Object>();
                        return value.outerValue().equals("owner") ? 42 : 1;
                    }
                }
                """);
        assertTrue(segmentedGenerics.successful(), messages(segmentedGenerics));
        assertDiagnostic("""
                class Outer<T> { class Inner<U> { } }
                class Main {
                    Outer.Inner<String, Object> invalid;
                    public static int main(String[] args) { return 0; }
                }
                """, "expects 1 type argument(s) but received 2 on its final name segment");
        assertDiagnostic("""
                class Outer<T> { class Inner<U> { } }
                class Main {
                    Outer<String>.Inner invalid;
                    public static int main(String[] args) { return 0; }
                }
                """, "raw generic type 'Outer$Inner' is not supported");
        assertDiagnostic("""
                class Outer<T> { class Inner<U> { } }
                class Main {
                    Outer.Inner<String> invalid;
                    public static int main(String[] args) { return 0; }
                }
                """, "raw generic type 'Outer' is not supported");
        assertDiagnostic("""
                class Outer<T> { static class StaticPair<A, B> { } }
                class Main {
                    Outer<String>.StaticPair<Object> invalid;
                    public static int main(String[] args) { return 0; }
                }
                """, "cannot be selected from a parameterized type");

        CompilationArtifact staticBoundary = compile("""
                class Outer<T> {
                    static class Static<U> {
                        class Inner<V> { V value; Inner(V value) { this.value = value; } }
                    }
                }
                class Main {
                    public static int main(String[] args) {
                        Outer.Static<String> owner = new Outer.Static<String>();
                        Outer.Static<String>.Inner<Object> value =
                                owner.new Inner<Object>(new Object());
                        return value.value == null ? 1 : 42;
                    }
                }
                """);
        assertTrue(staticBoundary.successful(), messages(staticBoundary));
        assertDiagnostic("""
                class Outer<T> {
                    static class Static<U> { class Inner<V> { } }
                }
                class Main {
                    Outer<String>.Static<Object>.Inner<String> invalid;
                    public static int main(String[] args) { return 0; }
                }
                """, "cannot be selected from a parameterized type");

        CompilationArtifact invalidPackageArguments = compileSources(
                SourceFile.of("src/sample/Outer.iron", """
                        package sample;
                        public class Outer<T> { }
                        """),
                SourceFile.of("src/app/Main.iron", """
                        package app;
                        public class Main {
                            sample<String>.Outer<Object> invalid;
                            public static int main(String[] args) { return 0; }
                        }
                        """));
        assertTrue(!invalidPackageArguments.successful(),
                "type arguments on a package segment unexpectedly compiled");
        assertContains(messages(invalidPackageArguments),
                "type arguments cannot qualify top-level type 'sample.Outer'",
                "parameterized package-segment diagnostic");

        CompilationArtifact qualifiedSuper = compile("""
                class Outer {
                    class Inner {
                        int value;
                        Inner(int value) { this.value = value; }
                    }
                }
                class Derived extends Outer.Inner {
                    Derived(Outer outer, int value) { outer.super(value); }
                }
                class Main {
                    public static int main(String[] args) {
                        Outer outer = new Outer();
                        Derived value = new Derived(outer, 42);
                        return value.value;
                    }
                }
                """);
        assertTrue(qualifiedSuper.successful(), messages(qualifiedSuper));

        assertDiagnostic("""
                class Outer {
                    class Inner { int read() { return 1; } }
                    Inner make() { return new Inner(); }
                }
                class Main {
                    public static int main(String[] args) {
                        Outer outer = new Outer();
                        Outer.Inner inner = outer.make();
                        free outer;
                        return inner.read();
                    }
                }
                """, "allocation escapes through receiver of method 'make'");
        assertDiagnostic("""
                class Buffer {
                    private int[] values;
                    Buffer() { values = new int[1]; }
                    class View { int[] expose() { return values; } }
                    void grow() {
                        int[] previous = values;
                        values = new int[2];
                        free previous;
                    }
                }
                class Main { public static int main(String[] args) { return 0; } }
                """, "or a proven detached private backing array");

        CompilationArtifact dollarMember = compile("""
                class Main {
                    class A$B { int value() { return 42; } }
                    int run() { return new A$B().value(); }
                    public static int main(String[] args) { return new Main().run(); }
                }
                """);
        assertTrue(dollarMember.successful(), messages(dollarMember));

        CompilationArtifact inaccessibleEnclosing = compileSources(
                SourceFile.of("src/hidden/Container.iron", """
                        package hidden;
                        class Container { public static class Exposed { } }
                        """),
                SourceFile.of("src/app/Main.iron", """
                        package app;
                        public class Main {
                            hidden.Container.Exposed value;
                            public static int main(String[] args) { return 0; }
                        }
                        """));
        assertTrue(!inaccessibleEnclosing.successful(),
                "public member of inaccessible enclosing type unexpectedly compiled");
        assertContains(messages(inaccessibleEnclosing), "package-private in package 'hidden'",
                "inaccessible enclosing-type diagnostic");
    }

