    private void objectsLowerToTypedIr() {
        CompilationArtifact artifact = compile(objectProgram());
        assertTrue(artifact.successful(), messages(artifact));
        var program = artifact.program().orElseThrow();
        assertEquals(2, (int) program.classes().stream()
                .filter(type -> type.name().equals("Main") || type.name().equals("Counter"))
                .count(), "application IR class count");
        var counter = program.classes().stream()
                .filter(irClass -> irClass.name().equals("Counter")).findFirst().orElseThrow();
        assertEquals(2, counter.fields().size(), "Counter field count");
        assertEquals(0, counter.fields().getFirst().layoutIndex(), "first field layout index");
        assertTrue(counter.fields().get(1).type().equals(IrType.reference("Counter")),
                "reference field type was not preserved");
        var instructions = program.functions().stream()
                .flatMap(function -> function.blocks().stream())
                .flatMap(block -> block.instructions().stream()).toList();
        assertTrue(instructions.stream().anyMatch(IrAllocateInstruction.class::isInstance),
                "object allocation did not reach typed IR");
        assertTrue(instructions.stream().anyMatch(IrFieldLoadInstruction.class::isInstance),
                "field load did not reach typed IR");
        assertTrue(instructions.stream().anyMatch(IrFieldStoreInstruction.class::isInstance),
                "field store did not reach typed IR");
        assertTrue(instructions.stream().anyMatch(IrNullCheckInstruction.class::isInstance),
                "null check did not reach typed IR");
        String llvm = artifact.llvmIr().orElseThrow();
        assertContains(llvm, "%\"ironwood.class.Counter\" = type { ptr, i32, ptr }", "object layout");
        assertContains(llvm, "@\"ironwood.typeinfo.Counter\" = private constant", "object type metadata");
        assertContains(llvm, "call ptr @ironwood_allocate", "runtime allocation call");
        assertContains(llvm, "getelementptr inbounds %\"ironwood.class.Counter\"", "field lowering");
        assertContains(llvm, "icmp ne ptr", "catchable null-check predicate");
        assertContains(llvm, "@\"ironwood.Counter.add\"", "direct instance call");
    }

