    private void referenceUpcastsAreAccepted() {
        CompilationArtifact artifact = compile("""
                interface Root { int value(); }
                interface Leaf extends Root { }
                class Base implements Leaf { @Override public int value() { return 6; } }
                class Child extends Base { }
                class Main {
                    static Base toBase(Child child) { return child; }
                    static Root toRoot(Child child) { return child; }
                    static int readRoot(Root value) { return value.value(); }
                    public static int main(String[] args) {
                        Child child = new Child();
                        Base base = child;
                        Leaf leaf = child;
                        Root root = leaf;
                        base = child;
                        return readRoot(toRoot(child)) + toBase(child).value();
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        long conversions = artifact.program().orElseThrow().functions().stream()
                .flatMap(function -> function.blocks().stream())
                .flatMap(block -> block.instructions().stream())
                .filter(IrReferenceConversionInstruction.class::isInstance).count();
        assertTrue(conversions >= 6, "expected explicit typed-IR upcast conversions");
    }

    private void checkedReferenceCastsLowerToTypedCfg() throws Exception {
        CompilationArtifact artifact = compileWithStandardLibrary("""
                interface Tagged { }
                class Base { }
                class Child extends Base implements Tagged { }
                class Other extends Base { }
                class Main {
                    static Child narrow(Base value) { return (Child) value; }
                    static Tagged asTagged(Object value) { return (Tagged) value; }
                    public static int main(String[] args) {
                        Base base = new Child();
                        Child child = narrow(base);
                        Tagged tagged = asTagged(child);
                        Base absent = null;
                        Child missing = (Child) absent;
                        try {
                            Base other = new Other();
                            Child failure = (Child) other;
                            return failure == null ? 1 : 2;
                        } catch (ClassCastException expected) {
                            return tagged != null && missing == null ? 42 : 3;
                        }
                    }
                }
                """, "ironwood.lang.Throwable", "ironwood.lang.Exception",
                "ironwood.lang.RuntimeException", "ironwood.lang.ClassCastException");
        assertTrue(artifact.successful(), messages(artifact));
        var program = artifact.program().orElseThrow();
        var instructions = program.functions().stream()
                .flatMap(function -> function.blocks().stream())
                .flatMap(block -> block.instructions().stream()).toList();
        assertTrue(instructions.stream().filter(IrInstanceOfInstruction.class::isInstance).count() >= 4,
                "checked casts did not retain explicit membership tests");
        assertTrue(instructions.stream().anyMatch(instruction ->
                        instruction instanceof IrAllocateInstruction allocation
                                && allocation.className().equals("ironwood.lang.ClassCastException")),
                "checked cast failure did not allocate ClassCastException in typed IR");
        assertTrue(program.functions().stream().flatMap(function -> function.blocks().stream())
                        .map(block -> block.terminator())
                        .anyMatch(IrThrowTerminator.class::isInstance),
                "checked cast failure did not retain a typed throw terminator");
        assertTrue(instructions.stream().filter(IrReferenceConversionInstruction.class::isInstance).count() >= 4,
                "checked cast success did not retain pointer-preserving reference conversions");
        String llvm = artifact.llvmIr().orElseThrow();
        assertContains(llvm, "cast.type.test", "checked-cast LLVM type-test block");
        assertContains(llvm, "call i1 @\"ironwood.is_instance\"", "checked-cast membership lowering");
        assertContains(llvm, "ironwood.lang.ClassCastException", "checked-cast exception metadata");
    }

