    private void objectIsUniversalReferenceRoot() {
        CompilationArtifact artifact = compile("""
                interface Marker {}
                class Value implements Marker {}
                class Main {
                    public static int main(String[] args) {
                        Value value = new Value();
                        Marker marker = value;
                        Object classObject = value;
                        Object interfaceObject = marker;
                        int[] values = new int[2];
                        Object arrayObject = values;
                        if (!(values instanceof Object)) { return 1; }
                        if (!classObject.equals(value)) { return 2; }
                        if (!interfaceObject.equals(value)) { return 3; }
                        if (!arrayObject.equals(values)) { return 4; }
                        if (values == arrayObject) { return 42; }
                        return 5;
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
        var program = artifact.program().orElseThrow();
        var root = program.classes().stream()
                .filter(type -> type.name().equals("ironwood.lang.Object")).findFirst().orElseThrow();
        assertTrue(root.superclass().isEmpty(), "Object unexpectedly has a superclass");
        for (String name : List.of("Main", "Value")) {
            var type = program.classes().stream().filter(candidate -> candidate.name().equals(name))
                    .findFirst().orElseThrow();
            assertTrue(type.isClass(), name + " is not an IR class");
            assertEquals("ironwood.lang.Object", type.superclass().orElseThrow(),
                    name + " implicit superclass");
        }
        assertTrue(program.arrayTypes().stream()
                        .filter(array -> array.type().equals(IrType.array(IrType.I32)))
                        .anyMatch(array -> array.typeMembership().contains(root.typeId())),
                "int array descriptor is not an Object member");
        assertDiagnostic("class Main { public static int main(String[] args) { Object value = 1; return 0; } }",
                "cannot initialize ironwood.lang.Object variable 'value' with int value");
    }

    private void standardExceptionsProvideHierarchyAndMessages() throws Exception {
        CompilationArtifact artifact = compileWithStandardLibrary("""
                import ironwood.util.NoSuchElementException;
                class Main {
                    public static int main(String[] args) {
                        String message = "failure";
                        Throwable root = new Throwable(message);
                        Error error = new OutOfMemoryError(message);
                        Exception checked = new Exception();
                        RuntimeException runtime = new IllegalArgumentException(message);
                        runtime = new IllegalStateException();
                        runtime = new IndexOutOfBoundsException(message);
                        runtime = new ArrayIndexOutOfBoundsException();
                        runtime = new NegativeArraySizeException(message);
                        runtime = new UnsupportedOperationException();
                        runtime = new ArithmeticException(message);
                        runtime = new NullPointerException();
                        runtime = new ClassCastException(message);
                        runtime = new NoSuchElementException(message);
                        if (root.getMessage() != message) { return 1; }
                        if (checked.getMessage() != null) { return 2; }
                        try {
                            throw runtime;
                        } catch (RuntimeException failure) {
                            return 42;
                        } catch (Throwable failure) {
                            return 3;
                        }
                    }
                }
                """,
                "ironwood.lang.Throwable",
                "ironwood.lang.Error",
                "ironwood.lang.OutOfMemoryError",
                "ironwood.lang.Exception",
                "ironwood.lang.RuntimeException",
                "ironwood.lang.IllegalArgumentException",
                "ironwood.lang.IllegalStateException",
                "ironwood.lang.IndexOutOfBoundsException",
                "ironwood.lang.ArrayIndexOutOfBoundsException",
                "ironwood.lang.NegativeArraySizeException",
                "ironwood.lang.UnsupportedOperationException",
                "ironwood.lang.ArithmeticException",
                "ironwood.lang.NullPointerException",
                "ironwood.lang.ClassCastException",
                "ironwood.util.NoSuchElementException");
        assertTrue(artifact.successful(), messages(artifact));

        Map<String, String> expectedSuperclasses = Map.ofEntries(
                Map.entry("ironwood.lang.Throwable", "ironwood.lang.Object"),
                Map.entry("ironwood.lang.Error", "ironwood.lang.Throwable"),
                Map.entry("ironwood.lang.OutOfMemoryError", "ironwood.lang.Error"),
                Map.entry("ironwood.lang.Exception", "ironwood.lang.Throwable"),
                Map.entry("ironwood.lang.RuntimeException", "ironwood.lang.Exception"),
                Map.entry("ironwood.lang.IllegalArgumentException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.IllegalStateException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.IndexOutOfBoundsException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.ArrayIndexOutOfBoundsException",
                        "ironwood.lang.IndexOutOfBoundsException"),
                Map.entry("ironwood.lang.NegativeArraySizeException",
                        "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.UnsupportedOperationException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.ArithmeticException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.NullPointerException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.lang.ClassCastException", "ironwood.lang.RuntimeException"),
                Map.entry("ironwood.util.NoSuchElementException", "ironwood.lang.RuntimeException"));
        expectedSuperclasses.forEach((typeName, superclass) -> {
            var type = artifact.program().orElseThrow().classes().stream()
                    .filter(candidate -> candidate.name().equals(typeName))
                    .findFirst().orElseThrow(() -> new AssertionError("missing " + typeName));
            assertEquals(superclass, type.superclass().orElseThrow(),
                    typeName + " superclass");
        });
    }

