    private void instanceOfPatternsFollowDefiniteMatchScope() {
        CompilationArtifact artifact = compile("""
                class Dog { int sound() { return 6; } }
                class Main {
                    static int check(Object value) {
                        int result = 0;
                        if (value instanceof Dog dog && dog.sound() == 6) {
                            result += 1;
                        }
                        if (!(value instanceof Dog orDog) || orDog.sound() != 6) {
                            return 0;
                        }
                        if (!(value instanceof Dog guarded)) {
                            return 0;
                        }
                        result += guarded.sound();
                        boolean arm = value instanceof Dog conditional
                                ? conditional.sound() == 6 : false;
                        if (arm) { result += 1; }
                        while (!(value instanceof Dog afterWhile)) {
                            return 0;
                        }
                        result += afterWhile.sound();
                        for (; !(value instanceof Dog afterFor); ) {
                            return 0;
                        }
                        result += afterFor.sound();
                        int updateCount = 0;
                        for (; value instanceof Dog updateDog && updateCount < 1;
                                updateCount += updateDog.sound()) {
                            updateCount++;
                        }
                        result += updateCount;
                        if (!(value instanceof Dog captured)) {
                            return 0;
                        }
                        class Reader { int read() { return captured.sound(); } }
                        Reader reader = new Reader();
                        return result + reader.read() + continueGuard(value)
                                + breakGuard(value) + finallyGuard(value);
                    }
                    static int continueGuard(Object value) {
                        int attempts = 0;
                        while (attempts < 2) {
                            attempts++;
                            if (!(value instanceof Dog dog)) { continue; }
                            class Reader { int read() { return dog.sound(); } }
                            Reader reader = new Reader();
                            return reader.read();
                        }
                        return 0;
                    }
                    static int breakGuard(Object value) {
                        while (true) {
                            if (!(value instanceof Dog dog)) { break; }
                            return dog.sound();
                        }
                        return 0;
                    }
                    static int finallyGuard(Object value) {
                        if (!(value instanceof Dog dog)) {
                            try { }
                            finally { return 0; }
                        }
                        return dog.sound();
                    }
                    public static int main(String[] args) {
                        return check(new Dog()) == 51 ? 42 : 1;
                    }
                }
                """);
        assertTrue(artifact.successful(), messages(artifact));
    }

