    private void bootstrapRuntimeIsDiscovered() {
        RuntimeLibrary.Discovery discovery = RuntimeLibrary.discover();
        assertTrue(discovery.successful(), discovery.error());
        Path source = discovery.source().orElseThrow();
        assertTrue(Files.isRegularFile(source), "runtime source is missing");
        Path header = source.getParent().getParent().resolve("include/ironwood_runtime.h");
        assertTrue(Files.isRegularFile(header),
                "runtime header is missing");
        try {
            String declarations = Files.readString(header);
            assertContains(declarations, "ironwood_deallocate", "runtime free ABI");
            assertContains(declarations, "ironwood_throw", "runtime throw ABI");
            assertContains(declarations, "ironwood_exception_take", "runtime landing ABI");
            assertContains(declarations, "ironwood_exception_caught",
                    "runtime source-catch ABI");
            assertContains(declarations, "ironwood_exception_add_secondary",
                    "runtime secondary-association ABI");
            assertContains(declarations, "ironwood_exception_secondary_count",
                    "runtime secondary-count ABI");
            assertContains(declarations, "ironwood_exception_secondary_at",
                    "runtime secondary-access ABI");
            assertContains(declarations, "struct ironwood_trace_site",
                    "runtime trace-site layout");
            assertContains(declarations, "struct ironwood_trace_function",
                    "runtime trace-function layout");
            assertContains(declarations, "ironwood_trace_register",
                    "runtime trace-metadata registration ABI");
            assertContains(declarations, "ironwood_uncaught_exception", "runtime uncaught ABI");
        } catch (IOException exception) {
            throw new AssertionError("cannot read runtime header: " + exception.getMessage());
        }
    }

    private void runtimeAllocationAndDeallocationWorks() throws Exception {
        RuntimeLibrary.Discovery runtime = RuntimeLibrary.discover();
        assertTrue(runtime.successful(), runtime.error());
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path directory = Files.createTempDirectory("ironwood-runtime-free-test-");
        try {
            Path harness = directory.resolve("runtime_free_test.c");
            Files.writeString(harness, """
                    #include "ironwood_runtime.h"
                    #include <stddef.h>
                    int main(void) {
                        unsigned char *value = ironwood_allocate(64, NULL, NULL);
                        for (size_t index = 0; index < 64; index++) {
                            if (value[index] != 0) { return 1; }
                        }
                        value[0] = 42;
                        ironwood_deallocate(value);
                        uint64_t primary[4] = {0};
                        uint64_t first[4] = {0};
                        uint64_t second[4] = {0};
                        ironwood_exception_add_secondary(&first, &second);
                        ironwood_exception_add_secondary(&primary, &first);
                        if (ironwood_exception_secondary_count(&primary) != 2) { return 2; }
                        if (ironwood_exception_secondary_at(&primary, 0) != &first) { return 3; }
                        if (ironwood_exception_secondary_at(&primary, 1) != &second) { return 4; }
                        const struct ironwood_trace_site site = {0};
                        const struct ironwood_trace_function function = {0, &main};
                        ironwood_trace_register(&site, 1, &function, 1);
                        ironwood_throwable_trace_release(&primary);
                        ironwood_throwable_trace_release(&first);
                        ironwood_throwable_trace_release(&second);
                        return 0;
                    }
                    """, StandardCharsets.UTF_8);
            Path runtimeObject = directory.resolve("runtime.o");
            Path harnessObject = directory.resolve("harness.o");
            Path caseObject = directory.resolve("case.o");
            Path executable = directory.resolve("runtime-free-test");
            runCommand(List.of(toolchain.clang().toString(), "-std=c11", "-c",
                    runtime.source().orElseThrow().toString(), "-o", runtimeObject.toString()),
                    "runtime C compilation");
            Path include = runtime.source().orElseThrow().getParent().getParent().resolve("include");
            runCommand(List.of(toolchain.clang().toString(), "-std=c11", "-I", include.toString(),
                    "-c", harness.toString(), "-o", harnessObject.toString()),
                    "runtime harness compilation");
            runCommand(List.of(toolchain.clang().toString(), "-std=c11", "-c",
                    runtime.source().orElseThrow().getParent().resolve("ironwood_case.c").toString(),
                    "-o", caseObject.toString()), "Unicode helper compilation");
            runCommand(List.of(toolchain.clang().toString(), "--driver-mode=g++",
                    runtimeObject.toString(), harnessObject.toString(), caseObject.toString(),
                    "-o", executable.toString()), "runtime harness link");
            assertEquals(0, new ProcessBuilder(executable.toString()).start().waitFor(),
                    "runtime allocation/deallocation harness exit code");
        } finally {
            deleteTree(directory);
        }
    }

    private void llvmToolchainIsDiscovered() {
        ToolchainDiscovery discovery = LlvmToolchain.discover(null);
        assertTrue(discovery.successful(), discovery.error());
        assertEquals(LlvmToolchain.REQUIRED_MAJOR,
                Integer.parseInt(discovery.toolchain().orElseThrow().version().split("\\.")[0]),
                "LLVM major version");
        assertTrue(Files.isExecutable(discovery.toolchain().orElseThrow().llvmAs()), "llvm-as is not executable");
        assertTrue(Files.isExecutable(discovery.toolchain().orElseThrow().opt()), "opt is not executable");
        assertTrue(Files.isExecutable(discovery.toolchain().orElseThrow().llc()), "llc is not executable");
        assertTrue(Files.isExecutable(discovery.toolchain().orElseThrow().llvmObjcopy()),
                "llvm-objcopy is not executable");
        assertTrue(Files.isExecutable(discovery.toolchain().orElseThrow().clang()), "clang is not executable");
    }

    private void invalidLlvmHomeIsDiagnosed() {
        ToolchainDiscovery discovery = LlvmToolchain.discover(Path.of("definitely-not-an-llvm-home"));
        assertTrue(!discovery.successful(), "invalid LLVM home unexpectedly succeeded");
        assertContains(discovery.error(), "missing executable tool(s)", "toolchain diagnostic");
    }

    private void wrongLlvmMajorIsDiagnosed() throws IOException {
        Path temporaryDirectory = Files.createTempDirectory("ironwood-wrong-llvm-");
        try {
            Path bin = Files.createDirectories(temporaryDirectory.resolve("bin"));
            for (String tool : List.of("clang", "llvm-as", "opt", "llc", "llvm-objcopy")) {
                writeExecutable(bin.resolve(tool), "#!/bin/sh\nexit 0\n");
            }
            writeExecutable(bin.resolve("llvm-config"), "#!/bin/sh\necho 22.1.0\n");

            ToolchainDiscovery discovery = LlvmToolchain.discover(temporaryDirectory);
            assertTrue(!discovery.successful(), "LLVM 22 unexpectedly satisfied the LLVM 23 requirement");
            assertContains(discovery.error(), "Ironwood requires LLVM 23.x", "LLVM version diagnostic");
        } finally {
            deleteTree(temporaryDirectory);
        }
    }

