    private void versionFlagsReportCompilerVersion() throws IOException {
        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        String expected = "ironwoodc " + Files.readString(projectRoot.resolve("VERSION")).trim()
                + System.lineSeparator();
        for (String flag : List.of("--version", "-v")) {
            ByteArrayOutputStream stdout = new ByteArrayOutputStream();
            ByteArrayOutputStream stderr = new ByteArrayOutputStream();
            int compilerExit = Main.run(new String[]{flag},
                    new PrintStream(stdout, true, StandardCharsets.UTF_8),
                    new PrintStream(stderr, true, StandardCharsets.UTF_8));
            assertEquals(0, compilerExit, flag + " exit code");
            assertEquals(expected, stdout.toString(StandardCharsets.UTF_8), flag + " output");
            assertEquals("", stderr.toString(StandardCharsets.UTF_8), flag + " stderr");
        }
    }

    private void defaultOutputRunsNatively() throws Exception {
        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        Path compilerJar = projectRoot.resolve("compiler/build/ironwoodc.jar");
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path temporaryDirectory = Files.createTempDirectory("ironwoodc-default-output-");
        try {
            Path sourceDirectory = Files.createDirectories(
                    temporaryDirectory.resolve("org/ironwood/basic"));
            Path source = sourceDirectory.resolve("Main.iron");
            Files.copy(projectRoot.resolve(
                    "examples/basic/src/main/ironwood/org/ironwood/basic/Main.iron"), source);
            Path java = Path.of(System.getProperty("java.home"), "bin", "java");
            Process compiler = new ProcessBuilder(java.toString(), "-jar", compilerJar.toString(),
                    temporaryDirectory.relativize(source).toString())
                    .directory(temporaryDirectory.toFile())
                    .redirectErrorStream(true)
                    .start();
            String compilerOutput = new String(compiler.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
            int compilerExit = compiler.waitFor();
            Path legacyExecutable = sourceDirectory.resolve("Main");
            Path ironClass = sourceDirectory.resolve("Main.ironclass");
            assertEquals(0, compilerExit, "default-output compiler exit; output: " + compilerOutput);
            assertTrue(!Files.exists(legacyExecutable),
                    "ordinary compilation unexpectedly linked " + legacyExecutable);
            assertTrue(Files.isRegularFile(ironClass), "main class did not produce Main.ironclass");
            assertEquals("org.ironwood.basic.Main", IronClass.read(ironClass).entryPoint().orElseThrow(),
                    "main ironclass entry-point metadata");
            assertContains(compilerOutput, "org/ironwood/basic/Main.ironclass",
                    "default-output build message");

            ByteArrayOutputStream outputWithoutLinkError = new ByteArrayOutputStream();
            int outputWithoutLinkExit = Main.run(new String[]{source.toString(), "-o",
                            temporaryDirectory.resolve("implicit-link").toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(outputWithoutLinkError, true, StandardCharsets.UTF_8));
            assertEquals(2, outputWithoutLinkExit, "-o without --link exit code");
            assertContains(outputWithoutLinkError.toString(StandardCharsets.UTF_8),
                    "-o requires --link", "explicit link-mode diagnostic");

            ByteArrayOutputStream sourceLinkError = new ByteArrayOutputStream();
            int sourceLinkExit = Main.run(new String[]{"--link", source.toString(),
                            "--llvm-home", toolchain.home().toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(sourceLinkError, true, StandardCharsets.UTF_8));
            assertEquals(2, sourceLinkExit, "source input was unexpectedly accepted by --link");
            assertContains(sourceLinkError.toString(StandardCharsets.UTF_8),
                    "--link does not accept source files; compile them first",
                    "strict link input diagnostic");

            ByteArrayOutputStream linkSourcePathError = new ByteArrayOutputStream();
            int linkSourcePathExit = Main.run(new String[]{"--link", "--source-path", ".",
                            "--main-class", "org.ironwood.basic.Main"},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(linkSourcePathError, true, StandardCharsets.UTF_8));
            assertEquals(2, linkSourcePathExit, "source path was unexpectedly accepted by --link");
            assertContains(linkSourcePathError.toString(StandardCharsets.UTF_8),
                    "--source-path cannot be combined with --link; link compiled classes instead",
                    "strict link source-path diagnostic");

            Path classes = temporaryDirectory.resolve("classes");
            ByteArrayOutputStream classOnlyError = new ByteArrayOutputStream();
            int classOnlyExit = Main.run(new String[]{source.toString(), "-d", classes.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(classOnlyError, true, StandardCharsets.UTF_8));
            assertEquals(0, classOnlyExit, "main class-only compiler exit; stderr: "
                    + classOnlyError.toString(StandardCharsets.UTF_8));
            assertTrue(Files.isRegularFile(classes.resolve("org/ironwood/basic/Main.ironclass")),
                    "-d did not produce a package-structured Main.ironclass");

            Process defaultLinker = new ProcessBuilder(java.toString(), "-jar", compilerJar.toString(),
                    "--link", "--main-class", "org.ironwood.basic.Main",
                    "--llvm-home", toolchain.home().toString())
                    .directory(temporaryDirectory.toFile())
                    .redirectErrorStream(true)
                    .start();
            String defaultLinkOutput = new String(defaultLinker.getInputStream().readAllBytes(),
                    StandardCharsets.UTF_8);
            int defaultLinkExit = defaultLinker.waitFor();
            Path defaultExecutable = temporaryDirectory.resolve("Main");
            assertEquals(0, defaultLinkExit, "default link exit; output: " + defaultLinkOutput);
            assertTrue(Files.isExecutable(defaultExecutable),
                    "default classpath link output is not executable: " + defaultExecutable);
            assertEquals(42, new ProcessBuilder(defaultExecutable.toString()).start().waitFor(),
                    "default classpath link native process exit code");

            Path linkedFromClass = temporaryDirectory.resolve("linked-from-class");
            ByteArrayOutputStream linkFromClassError = new ByteArrayOutputStream();
            int linkFromClassExit = Main.run(new String[]{"--link", "-cp", classes.toString(),
                            "--main-class", "org.ironwood.basic.Main", "-o", linkedFromClass.toString(),
                            "--llvm-home", toolchain.home().toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(linkFromClassError, true, StandardCharsets.UTF_8));
            assertEquals(0, linkFromClassExit, "link-from-class compiler exit; stderr: "
                    + linkFromClassError.toString(StandardCharsets.UTF_8));
            assertEquals(42, new ProcessBuilder(linkedFromClass.toString()).start().waitFor(),
                    "native program linked from Main.ironclass exit code");

            ByteArrayOutputStream missingMainClassError = new ByteArrayOutputStream();
            int missingMainClassExit = Main.run(new String[]{"--link", "-cp",
                            classes.toString(), "--main-class", "org.ironwood.basic.Missing"},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(missingMainClassError, true, StandardCharsets.UTF_8));
            assertEquals(1, missingMainClassExit, "missing classpath main exit code");
            assertContains(missingMainClassError.toString(StandardCharsets.UTF_8),
                    "cannot find class 'org.ironwood.basic.Missing' on the class path",
                    "classpath-only main lookup diagnostic");

            Path other = writeSource(temporaryDirectory, "other/Other.iron", """
                    package examples.other;
                    public class Other { public static int main(String[] args) { return 7; } }
                    """);
            Path multipleMainClasses = temporaryDirectory.resolve("multiple-main-classes");
            ByteArrayOutputStream multipleMainError = new ByteArrayOutputStream();
            int multipleMainExit = Main.run(new String[]{source.toString(), other.toString(),
                            "-d", multipleMainClasses.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(multipleMainError, true, StandardCharsets.UTF_8));
            assertEquals(0, multipleMainExit, "multiple main classes should compile with -d; stderr: "
                    + multipleMainError.toString(StandardCharsets.UTF_8));
            assertTrue(Files.isRegularFile(
                            multipleMainClasses.resolve("examples/other/Other.ironclass")),
                    "second main class did not use the uniform class format");
            ByteArrayOutputStream missingSelectionError = new ByteArrayOutputStream();
            int missingSelectionExit = Main.run(new String[]{"--link", "-cp",
                            multipleMainClasses.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(missingSelectionError, true, StandardCharsets.UTF_8));
            assertEquals(2, missingSelectionExit, "--link unexpectedly inferred a main class");
            assertContains(missingSelectionError.toString(StandardCharsets.UTF_8),
                    "--link requires --main-class <qualified-name>",
                    "mandatory main-class diagnostic");

            Path selectedProgram = temporaryDirectory.resolve("selected-program");
            ByteArrayOutputStream selectedEntryError = new ByteArrayOutputStream();
            int selectedEntryExit = Main.run(new String[]{"--link", "-cp",
                            multipleMainClasses.toString(), "--main-class", "examples.other.Other",
                            "-o", selectedProgram.toString(),
                            "--llvm-home", toolchain.home().toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(selectedEntryError, true, StandardCharsets.UTF_8));
            assertEquals(0, selectedEntryExit, "selected main compiler exit; stderr: "
                    + selectedEntryError.toString(StandardCharsets.UTF_8));
            assertEquals(7, new ProcessBuilder(selectedProgram.toString()).start().waitFor(),
                    "selected main native process exit code");
        } finally {
            deleteTree(temporaryDirectory);
        }
    }

