    private void classPathAliasesLoadClasses() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-class-path-");
        try {
            Path answer = writeSource(root, "library/com/lib/Answer.iron", """
                    package com.lib;
                    public class Answer {
                        public static int value() { return 42; }
                    }
                    """);
            ByteArrayOutputStream adjacentError = new ByteArrayOutputStream();
            int adjacentExit = Main.run(new String[]{answer.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(adjacentError, true, StandardCharsets.UTF_8));
            assertEquals(0, adjacentExit, "default class-only compiler exit; stderr: "
                    + adjacentError.toString(StandardCharsets.UTF_8));
            assertTrue(Files.isRegularFile(answer.resolveSibling("Answer.ironclass")),
                    "class without main did not produce an adjacent .ironclass");

            Path classes = root.resolve("classes");
            ByteArrayOutputStream classError = new ByteArrayOutputStream();
            int classExit = Main.run(new String[]{answer.toString(), "-d", classes.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(classError, true, StandardCharsets.UTF_8));
            assertEquals(0, classExit, "class-only compiler exit; stderr: "
                    + classError.toString(StandardCharsets.UTF_8));
            Path answerClass = classes.resolve("com/lib/Answer.ironclass");
            assertTrue(Files.isRegularFile(answerClass), "Answer.ironclass was not created");
            assertTrue(IronClass.read(answerClass).entryPoint().isEmpty(),
                    "helper class unexpectedly has entry-point metadata");

            Path main = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.Answer;
                    public class Main {
                        public static int main(String[] args) { return Answer.value(); }
                    }
                    """);
            LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
            List<String> aliases = List.of("-cp", "-classpath", "--class-path");
            for (int index = 0; index < aliases.size(); index++) {
                String alias = aliases.get(index);
                Path executable = root.resolve("program-" + alias.replace('-', 'x'));
                Path applicationClasses = root.resolve("application-classes-" + index);
                Path classPathEntry = index == 0 ? answerClass : classes;
                ByteArrayOutputStream compileError = new ByteArrayOutputStream();
                int compilerExit = Main.run(new String[]{alias, classPathEntry.toString(),
                                "--source-path", root.resolve("no-sources").toString(), main.toString(),
                                "-d", applicationClasses.toString()},
                        new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                        new PrintStream(compileError, true, StandardCharsets.UTF_8));
                assertEquals(0, compilerExit, alias + " compiler exit; stderr: "
                        + compileError.toString(StandardCharsets.UTF_8));
                String linkClassPath = applicationClasses + java.io.File.pathSeparator + classPathEntry;
                ByteArrayOutputStream linkError = new ByteArrayOutputStream();
                int linkExit = Main.run(new String[]{"--link", alias, linkClassPath,
                                "--main-class", "com.app.Main", "-o", executable.toString(),
                                "--llvm-home", toolchain.home().toString()},
                        new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                        new PrintStream(linkError, true, StandardCharsets.UTF_8));
                assertEquals(0, linkExit, alias + " link exit; stderr: "
                        + linkError.toString(StandardCharsets.UTF_8));
                assertEquals(42, new ProcessBuilder(executable.toString()).start().waitFor(),
                        alias + " native exit code");
            }
        } finally {
            deleteTree(root);
        }
    }

    private void overloadsSurviveClassPath() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-overload-classpath-");
        try {
            Path library = writeSource(root, "library/com/lib/Calculator.iron", """
                    package com.lib;
                    public class Calculator {
                        int seed;
                        public Calculator() { this(40); }
                        public Calculator(int seed) { this.seed = seed; }
                        public int add(int value) { return seed + value; }
                        public int add(boolean value) { if (value) { return seed + 2; } return seed; }
                    }
                    """);
            Path libraryClasses = root.resolve("library-classes");
            assertMainRun(new String[]{library.toString(), "-d", libraryClasses.toString()},
                    0, "overloaded library compilation");

            Path application = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.Calculator;
                    public class Main {
                        public static int main(String[] args) {
                            Calculator calculator = new Calculator();
                            return calculator.add(true);
                        }
                    }
                    """);
            Path applicationClasses = root.resolve("application-classes");
            assertMainRun(new String[]{"-cp", libraryClasses.toString(), "--source-path",
                            root.resolve("no-sources").toString(), application.toString(),
                            "-d", applicationClasses.toString()},
                    0, "overloaded application compilation");

            Path executable = root.resolve("program");
            LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
            String classPath = applicationClasses + java.io.File.pathSeparator + libraryClasses;
            assertMainRun(new String[]{"--link", "-cp", classPath, "--main-class", "com.app.Main",
                            "-o", executable.toString(), "--llvm-home", toolchain.home().toString()},
                    0, "overloaded class-path link");
            assertEquals(42, new ProcessBuilder(executable.toString()).start().waitFor(),
                    "overloaded class-path native exit code");
        } finally {
            deleteTree(root);
        }
    }

