    private void finallySemanticsSurviveDistributionRoundTrips() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-finally-distribution-");
        try {
            Path libraryRoot = root.resolve("library");
            Path resource = writeSource(libraryRoot, "com/lib/Resource.iron", """
                    package com.lib;
                    public class Resource implements AutoCloseable {
                        static class PrimaryFailure extends Exception { }
                        static class CleanupFailure extends Exception { }
                        public Resource() { }
                        @Override public void close() throws CleanupFailure {
                            throw new CleanupFailure();
                        }
                        public static int transfers() {
                            long baseline = System.liveAllocationCount();
                            for (int i = 0; i < 3; i++) {
                                Resource temporary = new Resource();
                                try { continue; } finally { free temporary; }
                            }
                            Resource ended = new Resource();
                            done: { try { break done; } finally { free ended; } }
                            int value = switch (0) {
                                default -> {
                                    Resource helper = new Resource();
                                    try { yield 42; } finally { free helper; }
                                }
                            };
                            if (System.liveAllocationCount() != baseline) { return 2; }
                            return value;
                        }
                        public static int verify()
                                throws PrimaryFailure, CleanupFailure {
                            Resource resource = new Resource();
                            try {
                                try { throw new PrimaryFailure(); }
                                finally {
                                    try { resource.close(); }
                                    finally { free resource; }
                                }
                            } catch (PrimaryFailure primary) {
                                return primary.getSecondaryExceptionCount() == 1
                                        && primary.getSecondaryException(0)
                                                instanceof CleanupFailure ? transfers() : 1;
                            }
                        }
                    }
                    """);
            Path application = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.Resource;
                    public class Main {
                        public static int main(String[] args) throws Exception {
                            return Resource.verify();
                        }
                    }
                    """);

            Path discoveredClasses = root.resolve("discovered-classes");
            assertMainRun(new String[]{"--source-path", libraryRoot.toString(),
                    application.toString(), "-d", discoveredClasses.toString()}, 0,
                    "finally source-path compilation");
            assertTrue(Files.isRegularFile(discoveredClasses.resolve("com/lib/Resource.ironclass")),
                    "finally implementation was not emitted from source-path discovery");
            Path discoveredExecutable = root.resolve("source-program");
            assertMainRun(new String[]{"--link", "-cp", discoveredClasses.toString(),
                    "--main-class", "com.app.Main", "-o", discoveredExecutable.toString()}, 0,
                    "finally source-path link");
            assertEquals(42, new ProcessBuilder(discoveredExecutable.toString()).start().waitFor(),
                    "finally source-path native exit");

            Path libraryClasses = root.resolve("library-classes");
            assertMainRun(new String[]{resource.toString(), "-d", libraryClasses.toString()}, 0,
                    "finally library compilation");
            Path classApplication = root.resolve("class-application");
            assertMainRun(new String[]{"-cp", libraryClasses.toString(), "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", classApplication.toString()}, 0, "finally ironclass compilation");
            Path classExecutable = root.resolve("class-program");
            assertMainRun(new String[]{"--link", "-cp",
                    classApplication + java.io.File.pathSeparator + libraryClasses,
                    "--main-class", "com.app.Main", "-o", classExecutable.toString()}, 0,
                    "finally ironclass link");
            assertEquals(42, new ProcessBuilder(classExecutable.toString()).start().waitFor(),
                    "finally ironclass native exit");
            Path archive = root.resolve("finally-library.ironjar");
            ByteArrayOutputStream archiveError = new ByteArrayOutputStream();
            int archiveExit = IronJarMain.run(new String[]{"--create", "--file", archive.toString(),
                            libraryClasses.resolve("com/lib/Resource.ironclass").toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(archiveError, true, StandardCharsets.UTF_8));
            assertEquals(0, archiveExit, "finally archive creation; stderr: "
                    + archiveError.toString(StandardCharsets.UTF_8));

            Path applicationClasses = root.resolve("application-classes");
            assertMainRun(new String[]{"-cp", archive.toString(), "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", applicationClasses.toString()}, 0,
                    "finally archive class-path compilation");
            Path executable = root.resolve("program");
            String classPath = applicationClasses + java.io.File.pathSeparator + archive;
            assertMainRun(new String[]{"--link", "-cp", classPath, "--main-class", "com.app.Main",
                    "-o", executable.toString()}, 0, "finally archive explicit link");
            assertEquals(42, new ProcessBuilder(executable.toString()).start().waitFor(),
                    "finally archive native exit");
        } finally {
            deleteTree(root);
        }
    }

    private void nestedTypesSurviveDistributionRoundTrips() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-nested-types-distribution-");
        try {
            Path libraryRoot = root.resolve("library");
            Path library = writeSource(libraryRoot, "com/lib/Outer.iron", """
                    package com.lib;
                    public class Outer {
                        private int base;
                        public Outer(int base) { this.base = base; }
                        public class Inner {
                            public Inner() { }
                            public int value() { return base; }
                        }
                        public static class Nested {
                            public static int value() { return 2; }
                        }
                        public static class Unused {
                            public static int value() { return 99; }
                            public static String text() { return "DEAD-ONLY"; }
                            public static int[] values() { return new int[1]; }
                        }
                    }
                    """);
            Path unused = writeSource(libraryRoot, "com/lib/Unused.iron", """
                    package com.lib;
                    public class Unused { public static int value() { return 100; } }
                    """);
            Path application = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.Outer;
                    public class Main {
                        public static int main(String[] args) {
                            Outer outer = new Outer(40);
                            Outer.Inner inner = outer.new Inner();
                            return inner.value() + Outer.Nested.value();
                        }
                    }
                    """);

            Path discoveredClasses = root.resolve("discovered-classes");
            assertMainRun(new String[]{"--source-path", libraryRoot.toString(),
                    application.toString(), "-d", discoveredClasses.toString()}, 0,
                    "nested-type source-path compilation");
            assertTrue(Files.isRegularFile(discoveredClasses.resolve("com/lib/Outer.ironclass")),
                    "nested-type source-path outer artifact was not emitted");
            assertTrue(Files.isRegularFile(discoveredClasses.resolve("com/lib/Outer$Inner.ironclass")),
                    "nested-type source-path inner artifact was not emitted");
            assertTrue(Files.isRegularFile(discoveredClasses.resolve("com/lib/Outer$Nested.ironclass")),
                    "nested-type source-path static artifact was not emitted");

            Path libraryClasses = root.resolve("library-classes");
            assertMainRun(new String[]{library.toString(), unused.toString(),
                    "-d", libraryClasses.toString()}, 0,
                    "nested-type library class compilation");
            Path classApplicationClasses = root.resolve("class-application-classes");
            assertMainRun(new String[]{"-cp", libraryClasses.toString(), "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", classApplicationClasses.toString()}, 0,
                    "nested-type ironclass class-path compilation");
            Path classExecutable = root.resolve("class-program");
            String classPath = classApplicationClasses + java.io.File.pathSeparator + libraryClasses;
            assertMainRun(new String[]{"--link", "-cp", classPath,
                    "--main-class", "com.app.Main", "-o", classExecutable.toString()}, 0,
                    "nested-type ironclass explicit link");
            assertEquals(42, new ProcessBuilder(classExecutable.toString()).start().waitFor(),
                    "nested-type ironclass native exit");

            Path archive = root.resolve("nested-types.ironjar");
            ByteArrayOutputStream archiveError = new ByteArrayOutputStream();
            int archiveExit = IronJarMain.run(new String[]{"--create", "--file", archive.toString(),
                            libraryClasses.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(archiveError, true, StandardCharsets.UTF_8));
            assertEquals(0, archiveExit, "nested-type archive creation; stderr: "
                    + archiveError.toString(StandardCharsets.UTF_8));
            Path archiveApplicationClasses = root.resolve("archive-application-classes");
            assertMainRun(new String[]{"-cp", archive.toString(), "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", archiveApplicationClasses.toString()}, 0,
                    "nested-type ironjar class-path compilation");
            Path archiveExecutable = root.resolve("archive-program");
            Path llvm = root.resolve("archive-program.ll");
            String archiveClassPath = archiveApplicationClasses + java.io.File.pathSeparator + archive;
            assertMainRun(new String[]{"--link", "-cp", archiveClassPath,
                    "--main-class", "com.app.Main", "-o", archiveExecutable.toString(),
                    "--emit-llvm", llvm.toString()}, 0,
                    "nested-type ironjar explicit link");
            assertEquals(42, new ProcessBuilder(archiveExecutable.toString()).start().waitFor(),
                    "nested-type ironjar native exit");
            String linkedLlvm = Files.readString(llvm);
            assertTrue(!linkedLlvm.contains("Outer$Unused"),
                    "unused same-unit nested type entered LLVM functions or type metadata");
            assertTrue(!linkedLlvm.contains("DEAD-ONLY"),
                    "unused nested-type string literal entered LLVM metadata");
            assertTrue(!linkedLlvm.contains("int[]"),
                    "unused nested-type array descriptor entered LLVM metadata");
            assertTrue(!linkedLlvm.contains("com.lib.Unused"),
                    "unused archive sibling entered the nested-type closed world");
        } finally {
            deleteTree(root);
        }
    }

    private void lexicalTypesSurviveDistributionRoundTrips() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-lexical-types-distribution-");
        try {
            Path libraryRoot = root.resolve("library");
            Path library = writeSource(libraryRoot, "com/lib/LexicalLibrary.iron", """
                    package com.lib;
                    public class LexicalLibrary {
                        private int outer;
                        public LexicalLibrary(int outer) { this.outer = outer; }
                        public int answer(int seed) {
                            int captured = seed;
                            class Local<T> {
                                int amount;
                                <U extends T> Local(U ignored, int base, int first, int second) {
                                    amount = base + first + second;
                                }
                                int value() {
                                    com.dep.Token token = new com.dep.Token(outer + captured);
                                    return token.adjust(amount);
                                }
                            }
                            Local<String> value = new <String> Local<>("ignored", 5, 10, 10) {
                                @Override int value() { return super.value() + captured + 7; }
                            };
                            return value.value();
                        }
                    }
                    """);
            Path dependency = writeSource(libraryRoot, "com/dep/Token.iron", """
                    package com.dep;
                    public class Token {
                        private int base;
                        public Token(int base) { this.base = base; }
                        public int adjust(int amount) { return base + amount; }
                    }
                    """);
            Path application = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.LexicalLibrary;
                    public class Main {
                        public static int main(String[] args) {
                            return new LexicalLibrary(4).answer(3);
                        }
                    }
                    """);

            CompilationArtifact sourceArtifact = new CompilerPipeline().analyze(
                    List.of(SourceFile.read(library), SourceFile.read(dependency)));
            assertTrue(sourceArtifact.valid(), messages(sourceArtifact));
            List<String> sourceShape = lexicalDistributionShape(sourceArtifact,
                    "com.lib.LexicalLibrary");
            assertEquals(List.of("com.lib.LexicalLibrary$1Local",
                            "com.lib.LexicalLibrary$2"),
                    lexicalClassNames(sourceArtifact, "com.lib.LexicalLibrary"),
                    "deterministic lexical type identities");
            assertTrue(sourceShape.stream().anyMatch(value -> value.contains(":<enclosing>:")),
                    "lexical distribution shape omitted the hidden enclosing field");
            assertTrue(sourceShape.stream().anyMatch(value -> value.contains(":<capture:")),
                    "lexical distribution shape omitted the effectively-final capture field");
            assertTrue(sourceShape.stream().anyMatch(value -> value.contains("<super-enclosing>")),
                    "anonymous forwarding constructor omitted the super-enclosing parameter");
            assertTrue(sourceShape.stream().anyMatch(value -> value.contains("first:int"))
                            && sourceShape.stream().anyMatch(value -> value.contains("second:int")),
                    "lexical constructor shape omitted fixed parameters");

            Path discoveredClasses = root.resolve("discovered-classes");
            assertMainRun(new String[]{"--source-path", libraryRoot.toString(),
                    application.toString(), "-d", discoveredClasses.toString()}, 0,
                    "lexical source-path compilation");
            assertTrue(Files.isRegularFile(
                            discoveredClasses.resolve("com/lib/LexicalLibrary.ironclass")),
                    "lexical source-path owner artifact was not emitted");
            assertTrue(Files.isRegularFile(
                            discoveredClasses.resolve("com/dep/Token.ironclass")),
                    "dependency used only inside a lexical class was not discovered");
            assertTrue(classArtifactPaths(discoveredClasses).stream()
                            .noneMatch(path -> path.contains("$")),
                    "source-path compilation emitted an independently addressable lexical artifact");

            Path libraryClasses = root.resolve("library-classes");
            assertMainRun(new String[]{"--source-path", libraryRoot.toString(),
                    library.toString(), "-d", libraryClasses.toString()}, 0,
                    "lexical library class compilation");
            assertEquals(List.of("com/dep/Token.ironclass",
                            "com/lib/LexicalLibrary.ironclass"),
                    classArtifactPaths(libraryClasses),
                    "owner-payload class artifacts");
            Path ownerClass = libraryClasses.resolve("com/lib/LexicalLibrary.ironclass");
            assertEquals(Set.of("com.lib.LexicalLibrary"),
                    IronClass.read(ownerClass).declaredTypes(),
                    "owner artifact type index");

            Path unavailableSources = root.resolve("source-unavailable");
            Files.move(libraryRoot, unavailableSources);
            Path missingSources = root.resolve("missing-source");

            SourceLoadResult classLoad = new SourceSetLoader(List.of(missingSources),
                    List.of(libraryClasses)).load(List.of(),
                    List.of("com.lib.LexicalLibrary"));
            assertTrue(classLoad.diagnostics().isEmpty(), classLoad.diagnostics().toString());
            CompilationArtifact classArtifact = new CompilerPipeline().analyze(classLoad.sources());
            assertTrue(classArtifact.valid(), messages(classArtifact));
            assertEquals(sourceShape, lexicalDistributionShape(classArtifact,
                            "com.lib.LexicalLibrary"),
                    "ironclass lexical identities hidden fields and constructor ABI");

            SourceLoadResult directLexicalLoad = new SourceSetLoader(List.of(missingSources),
                    List.of(libraryClasses)).load(List.of(),
                    List.of("com.lib.LexicalLibrary$1Local"));
            assertContains(directLexicalLoad.diagnostics().stream()
                            .map(diagnostic -> diagnostic.message())
                            .reduce((left, right) -> left + "; " + right).orElse("no diagnostics"),
                    "cannot find class 'com.lib.LexicalLibrary$1Local'",
                    "lexical class direct-address rejection");

            Path classApplicationClasses = root.resolve("class-application-classes");
            assertMainRun(new String[]{"-cp", libraryClasses.toString(), "--source-path",
                    missingSources.toString(), application.toString(),
                    "-d", classApplicationClasses.toString()}, 0,
                    "lexical ironclass class-path compilation without original source");
            Path classExecutable = root.resolve("class-program");
            String classPath = classApplicationClasses + java.io.File.pathSeparator + libraryClasses;
            assertMainRun(new String[]{"--link", "-cp", classPath,
                    "--main-class", "com.app.Main", "-o", classExecutable.toString()}, 0,
                    "lexical ironclass classpath-only explicit link");
            assertEquals(42, new ProcessBuilder(classExecutable.toString()).start().waitFor(),
                    "lexical ironclass native exit");

            Path archive = root.resolve("lexical-library.ironjar");
            ByteArrayOutputStream archiveError = new ByteArrayOutputStream();
            int archiveExit = IronJarMain.run(new String[]{"--create", "--file",
                            archive.toString(), libraryClasses.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(archiveError, true, StandardCharsets.UTF_8));
            assertEquals(0, archiveExit, "lexical archive creation; stderr: "
                    + archiveError.toString(StandardCharsets.UTF_8));
            assertEquals(Set.of("com.dep.Token", "com.lib.LexicalLibrary"),
                    IronJar.read(archive).declaredTypes(), "lexical archive type index");

            SourceLoadResult archiveLoad = new SourceSetLoader(List.of(missingSources),
                    List.of(archive)).load(List.of(), List.of("com.lib.LexicalLibrary"));
            assertTrue(archiveLoad.diagnostics().isEmpty(), archiveLoad.diagnostics().toString());
            CompilationArtifact archiveArtifact = new CompilerPipeline().analyze(
                    archiveLoad.sources());
            assertTrue(archiveArtifact.valid(), messages(archiveArtifact));
            assertEquals(sourceShape, lexicalDistributionShape(archiveArtifact,
                            "com.lib.LexicalLibrary"),
                    "ironjar lexical identities hidden fields and constructor ABI");

            Path archiveApplicationClasses = root.resolve("archive-application-classes");
            assertMainRun(new String[]{"-cp", archive.toString(), "--source-path",
                    missingSources.toString(), application.toString(),
                    "-d", archiveApplicationClasses.toString()}, 0,
                    "lexical ironjar class-path compilation without original source");
            Path archiveExecutable = root.resolve("archive-program");
            String archiveClassPath = archiveApplicationClasses
                    + java.io.File.pathSeparator + archive;
            assertMainRun(new String[]{"--link", "-cp", archiveClassPath,
                    "--main-class", "com.app.Main", "-o", archiveExecutable.toString()}, 0,
                    "lexical ironjar classpath-only explicit link");
            assertEquals(42, new ProcessBuilder(archiveExecutable.toString()).start().waitFor(),
                    "lexical ironjar native exit");
        } finally {
            deleteTree(root);
        }
    }

    private void genericTypesSurviveDistributionRoundTrips() throws Exception {
        Path root = Files.createTempDirectory("ironwoodc-generic-distribution-");
        try {
            Path libraryRoot = root.resolve("library");
            writeSource(libraryRoot, "com/lib/Box.iron", """
                    package com.lib;
                    public class Box<T extends CharSequence> {
                        private T value;
                        public <U extends T> Box(U value, T remaining) {
                            this.value = remaining;
                        }
                        public T get() { return value; }
                        public void set(T value) { this.value = value; }
                        public <U extends T> U echo(U input) { return input; }
                        public <U extends CharSequence> U read(Box<U> source) {
                            return source.get();
                        }
                        public <U extends CharSequence> void write(Box<U> target, U input) {
                            target.set(input);
                        }
                        public class Entry<U extends T> {
                            private U entry;
                            public Entry(U entry) { this.entry = entry; }
                            public U get() { return entry; }
                        }
                    }
                    """);
            Path unused = writeSource(libraryRoot, "com/lib/Unused.iron", """
                    package com.lib;
                    public class Unused<T> { public Unused() { } }
                    """);
            Path application = writeSource(root, "application/com/app/Main.iron", """
                    package com.app;
                    import com.lib.Box;
                    public class Main {
                        public static int main(String[] args) {
                            String value = "generic archive";
                            Box<String> box = new <String> Box<>(value, value);
                            Box<?> view = box;
                            Object read = view.get();
                            Object erased = box;
                            Box<?> checked = (Box<?>) erased;
                            Box<? extends CharSequence> producer = box;
                            CharSequence produced = box.read(producer);
                            Box<? super String> consumer = box;
                            box.write(consumer, value);
                            Box<String>.Entry<String> entry = box.new Entry<String>(box.echo(value));
                            if (checked instanceof Box<?> && read == value
                                    && produced == value && entry.get() == value
                                    && box.get() == value) { return 42; }
                            return 1;
                        }
                    }
                    """);

            Path discoveredClasses = root.resolve("discovered-classes");
            assertMainRun(new String[]{"--source-path", libraryRoot.toString(),
                    application.toString(), "-d", discoveredClasses.toString()}, 0,
                    "generic source-path compilation");
            assertTrue(Files.isRegularFile(discoveredClasses.resolve("com/lib/Box.ironclass")),
                    "generic source-path dependency was not emitted");
            assertMainRun(new String[]{unused.toString(), "-d", discoveredClasses.toString()}, 0,
                    "unused wildcard archive sibling compilation");

            Path archive = root.resolve("generic-library.ironjar");
            ByteArrayOutputStream archiveError = new ByteArrayOutputStream();
            int archiveExit = IronJarMain.run(new String[]{"--create", "--file", archive.toString(),
                            discoveredClasses.resolve("com/lib/Box.ironclass").toString(),
                            discoveredClasses.resolve("com/lib/Unused.ironclass").toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(archiveError, true, StandardCharsets.UTF_8));
            assertEquals(0, archiveExit, "generic archive creation; stderr: "
                    + archiveError.toString(StandardCharsets.UTF_8));

            Path applicationClasses = root.resolve("application-classes");
            assertMainRun(new String[]{"-cp", archive.toString(), "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", applicationClasses.toString()}, 0,
                    "generic archive class-path compilation");
            Path executable = root.resolve("program");
            Path llvm = root.resolve("program.ll");
            String classPath = applicationClasses + java.io.File.pathSeparator + archive;
            assertMainRun(new String[]{"--link", "-cp", classPath, "--main-class", "com.app.Main",
                    "-o", executable.toString(), "--emit-llvm", llvm.toString()}, 0,
                    "generic wildcard archive explicit link");
            Process genericProcess = new ProcessBuilder(executable.toString())
                    .redirectErrorStream(true).start();
            String genericOutput = new String(genericProcess.getInputStream().readAllBytes(),
                    StandardCharsets.UTF_8);
            assertEquals(42, genericProcess.waitFor(),
                    "generic wildcard archive native exit; output: " + genericOutput);
            assertTrue(!Files.readString(llvm).contains("com.lib.Unused"),
                    "unused wildcard archive sibling entered the closed world");
        } finally {
            deleteTree(root);
        }
    }

