            Path individualApplicationClasses = root.resolve("individual-application-classes");
            String individualLibraryPath = libraryClasses.resolve(
                    "com/lib/ConstantApi.ironclass") + java.io.File.pathSeparator
                    + libraryClasses.resolve("com/lib/InitializationHelper.ironclass");
            assertMainRun(new String[]{"-cp", individualLibraryPath, "--source-path",
                    root.resolve("missing-source").toString(), application.toString(),
                    "-d", individualApplicationClasses.toString()}, 0,
                    "static individual-class application compilation");
