    private void filesystemMutationCompatibilityRunsAtO3() throws Exception {
        Path root = Files.createTempDirectory("ironwood-file-mutations-");
        Path denied = root.resolve("denied.txt");
        Path work = root.resolve("work");
        boolean posix = Files.getFileStore(root).supportsFileAttributeView("posix");
        try {
            Files.writeString(denied, "denied");
            if (posix) {
                Files.setPosixFilePermissions(denied,
                        PosixFilePermissions.fromString("---------"));
            }
            Path classes = root.resolve("classes");
            assertMainRun(new String[]{"integration-tests/cases/stdlib_file_mutations.iron",
                    "-d", classes.toString()}, 0, "file mutation compilation");
            Path executable = root.resolve("file-mutations-O3");
            assertMainRun(new String[]{"--link", "-cp", classes.toString(), "--main-class",
                    "Main", "-o", executable.toString(), "-O3"}, 0,
                    "file mutation link");
            NativeResult result = posix
                    ? runNative(executable, root, Map.of(), work.toString(), denied.toString())
                    : runNative(executable, root, Map.of(), work.toString());
            assertEquals(42, result.exit(), "file mutation exit: " + result.stderr());
            assertEquals("", result.stdout(), "file mutation stdout");
            assertEquals("", result.stderr(), "file mutation stderr");
        } finally {
            if (posix && Files.exists(denied)) {
                Files.setPosixFilePermissions(denied,
                        PosixFilePermissions.fromString("rw-------"));
            }
            deleteTree(root);
        }
    }

