    private void directIntegerFormattingMatchesJava() throws Exception {
        int[] edges = {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0, 1,
                -1000000000, -100, -10, -9, 9, 10, 100, 1000000000};
        long[] wideEdges = {Long.MIN_VALUE, Long.MAX_VALUE, -1L, 0L, 1L,
                -1000000000000000000L, -100L, -10L, -9L, 9L, 10L, 100L, 1000000000000000000L};
        StringBuilder expected = new StringBuilder();
        int random = 123456789;
        long wideRandom = 987654321L;
        for (int index = 0; index < edges.length + 128; index++) {
            int value = index < edges.length ? edges[index] : random;
            long wideValue = index < edges.length ? wideEdges[index] : wideRandom;
            for (int radix = 0; radix <= 38; radix++) {
                expected.append(Integer.toString(value, radix)).append('\n');
            }
            expected.append(Long.toString(wideValue)).append('\n');
            expected.append("n=").append(value).append(':').append(wideValue).append('\n');
            random = random * 1664525 + 1013904223;
            wideRandom = wideRandom * 6364136223846793005L + 1442695040888963407L;
        }
        expected.append(Integer.toString(Integer.MIN_VALUE, Integer.MIN_VALUE)).append('\n');
        expected.append(Integer.toString(Integer.MAX_VALUE, Integer.MAX_VALUE)).append('\n');
        runFixtureAtO3("stdlib_formatting_differential.iron", "Main", 42,
                expected.toString(), "", Map.of());
    }

    private void directTextAllocationFailures() throws Exception {
        Path root = Files.createTempDirectory("ironwood-direct-text-failure-");
        try {
            Path fixtures = Path.of("integration-tests/cases").toAbsolutePath();
            for (String fixture : List.of("stdlib_formatting_allocation_failure",
                    "stdlib_subsequence_allocation_failure")) {
                Path classes = root.resolve(fixture);
                assertMainRun(new String[]{fixtures.resolve(fixture + ".iron").toString(),
                        "-d", classes.toString()}, 0, fixture + " compilation");
                for (int level : List.of(3)) {
                    Path executable = root.resolve(fixture + "-O" + level);
                    assertMainRun(new String[]{"--link", "-cp", classes.toString(),
                            "--main-class", "Main", "-o", executable.toString(), "-O" + level},
                            0, fixture + " link");
                    List<List<String>> cases = new ArrayList<>();
                    if (fixture.equals("stdlib_formatting_allocation_failure")) {
                        for (int kind = 0; kind < 8; kind++) {
                            cases.add(List.of("0", Integer.toString(kind), "true"));
                            cases.add(List.of("1", Integer.toString(kind), "false"));
                        }
                    } else {
                        cases.addAll(List.of(List.of("2", "1", "4", "oom"),
                                List.of("2", "0", "0", "oom"),
                                List.of("3", "1", "4", "success"),
                                List.of("3", "5", "5", "success")));
                        for (int[] range : List.of(new int[]{-1, 1}, new int[]{0, 6},
                                new int[]{3, 2}, new int[]{6, 6}, new int[]{0, -1},
                                new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE})) {
                            cases.add(List.of("3", Integer.toString(range[0]),
                                    Integer.toString(range[1]), "bounds"));
                        }
                    }
                    for (List<String> input : cases) {
                        NativeResult result = runNative(executable, root,
                                Map.of("IRONWOOD_ALLOCATION_LIMIT", input.getFirst()),
                                input.subList(1, input.size()).toArray(String[]::new));
                        assertEquals(42, result.exit(), fixture + " -O" + level + " " + input);
                        assertEquals("", result.stdout(), fixture + " stdout");
                        assertEquals("", result.stderr(), fixture + " stderr");
                    }
                }
            }
        } finally {
            deleteTree(root);
        }
    }

