    private void stringFormatIsRejectedDuringCompilation() throws Exception {
        List<String> calls = List.of(
                "String.format(\"%d items\", n)",
                "String.format(\"x=%d\", 7)",
                "String.format(\"%-6d|\", 42)",
                "String.format(\"%x\", 255)",
                "String.format(\"%e\", 1.0)",
                "String.format(\"%.2f\", 3.14159)",
                "String.format(\"%6d\", 42)",
                "String.format(\"%9.2f\", 150.44)",
                "String.format(\"%05d\", 42)",
                "String.format(pattern, n)",
                "String.format(pattern, integral)",
                "String.format(pattern, floating)");
        Path root = Files.createTempDirectory("ironwood-string-format-boundary-");
        try {
            List<String> arguments = new ArrayList<>();
            for (int index = 0; index < calls.size(); index++) {
                String name = "FormatCall" + index;
                Path source = writeSource(root, name + ".iron", "class " + name + " {\n\n"
                        + "    static String render(String pattern, int n, long integral, double floating) {\n\n"
                        + "        return " + calls.get(index) + ";\n"
                        + "    }\n}\n");
                arguments.add(source.toString());
            }
            arguments.addAll(List.of("-d", root.resolve("classes").toString()));
            ByteArrayOutputStream stderr = new ByteArrayOutputStream();
            int exit = Main.run(arguments.toArray(String[]::new),
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(stderr, true, StandardCharsets.UTF_8));
            String diagnostics = stderr.toString(StandardCharsets.UTF_8);
            assertEquals(1, exit, "String.format must fail at compilation; " + diagnostics);
            for (int index = 0; index < calls.size(); index++) {
                assertContains(diagnostics, "FormatCall" + index + ".iron:5:",
                        "caller source location for " + calls.get(index));
            }
            assertContains(diagnostics, "has no method 'format'", "missing String.format diagnostic");
        } finally {
            deleteTree(root);
        }
    }

