    private void floatingPointParsingMatchesJavaAtAllOptimizationLevels() throws Exception {
        List<String> inputs = new ArrayList<>(List.of(
                "0", "-0", "+0.0", "1.", ".5", "1e3", "-1E-3f",
                "+6.02214076e23D", "0x1.8p1", "-0X1.0P-149f",
                "0x1.fffffffffffffp1023", "1.4e-45", "3.4028235e38",
                "3.4028236e38", "4.9e-324", "1.7976931348623157e308",
                "1.7976931348623159e308", "NaN", "+NaN", "-NaN",
                "Infinity", "+Infinity", "-Infinity", " \t42.25\r\n",
                "\u001f1.0\u001f", "", " ", "+", "-", ".", "e1", "1e",
                "1e+", "1.2.3", "0x1", "0x.p1", "0x1p", "0x1p+",
                "NaNf", "Infinityd", "nan", "infinity", "1_0", "1,0",
                "１２.０", "\u00a01.0\u00a0"));
        String floatHalfMinimum = new BigDecimal(BigInteger.valueOf(5).pow(150), 150)
                .toPlainString();
        String doubleHalfMinimum = new BigDecimal(BigInteger.valueOf(5).pow(1075), 1075)
                .toPlainString();
        inputs.add(floatHalfMinimum);
        inputs.add(floatHalfMinimum + "0".repeat(1_200) + "1");
        inputs.add(doubleHalfMinimum);
        inputs.add(doubleHalfMinimum + "0".repeat(1_200) + "1");
        inputs.add("9".repeat(5_000) + "e-5000");
        inputs.add("1" + "0".repeat(5_000) + "e-5000");
        inputs.add("0x1." + "0".repeat(1_400) + "1p0");
        StringBuilder expected = new StringBuilder();
        for (String input : inputs) {
            try {
                expected.append(Float.toString(Float.parseFloat(input)));
            } catch (NumberFormatException exception) {
                expected.append("NumberFormatException");
            }
            expected.append('|');
            try {
                expected.append(Double.toString(Double.parseDouble(input)));
            } catch (NumberFormatException exception) {
                expected.append("NumberFormatException");
            }
            expected.append('\n');
        }

        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        Path fixture = projectRoot.resolve("integration-tests/cases/stdlib_floating_parse.iron");
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path root = Files.createTempDirectory("ironwood-floating-parse-");
        try {
            Path classes = root.resolve("classes");
            assertMainRun(new String[]{fixture.toString(), "-d", classes.toString()}, 0,
                    "floating parse fixture compilation");
            for (int level : List.of(3)) {
                Path executable = root.resolve("floating-parse-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(),
                                "--main-class", "Main", "-o", executable.toString(),
                                "-O" + level, "--llvm-home", toolchain.home().toString()},
                        0, "floating parse -O" + level + " link");
                NativeResult result = runNative(executable, root, Map.of(),
                        inputs.toArray(String[]::new));
                assertEquals(42, result.exit(), "floating parse -O" + level + " exit");
                assertEquals(expected.toString(), result.stdout(),
                        "floating parse -O" + level + " Java 21 differential output");
                assertEquals("", result.stderr(), "floating parse -O" + level + " stderr");
            }
        } finally {
            deleteTree(root);
        }
    }

