    private void u3OutOfMemory() throws Exception {
        Path root = Files.createTempDirectory("ironwood-u3-oom-");
        try {
            Path input = root.resolve("input.txt"); Files.writeString(input, "x".repeat(200) + "\n");
            Path output = root.resolve("output.txt");
            Path classes = root.resolve("classes");
            assertMainRun(new String[]{"integration-tests/cases/stdlib_u3_oom.iron", "-d", classes.toString()}, 0, "stream OOM compile");
            for (int level : List.of(3)) {
                Path executable = root.resolve("oom-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(), "--main-class", "Main",
                        "-o", executable.toString(), "-O" + level}, 0, "stream OOM link");
                for (int limit = 2; limit <= 11; limit++) {
                    NativeResult result = runNative(executable, root,
                            Map.of("IRONWOOD_ALLOCATION_LIMIT", Integer.toString(limit)), "reader", input.toString());
                    assertEquals(limit < 11 ? 42 : 0, result.exit(), "reader OOM " + limit + ": " + result.stderr());
                }
                for (String mode : List.of("bytes", "text")) {
                    int successLimit = mode.equals("text") ? 7 : 6;
                    for (int limit = 2; limit <= successLimit; limit++) {
                        NativeResult result = runNative(executable, root,
                                Map.of("IRONWOOD_ALLOCATION_LIMIT", Integer.toString(limit)), mode, input.toString());
                        assertEquals(limit < successLimit ? 42 : 0, result.exit(),
                                mode + " OOM " + limit + ": " + result.stderr());
                    }
                }
                for (int limit = 2; limit < 7; limit++) {
                    Files.deleteIfExists(output);
                    NativeResult result = runNative(executable, root,
                            Map.of("IRONWOOD_ALLOCATION_LIMIT", Integer.toString(limit)), "writer", output.toString());
                    assertEquals(42, result.exit(), "writer OOM " + limit + ": " + result.stderr());
                    assertTrue(!Files.exists(output), "failed construction opened/truncated its file");
                }
            }
        } finally { deleteTree(root); }
    }

    private void u3CliAcrossArtifacts() throws Exception {
        Path root = Files.createTempDirectory("ironwood-u3-cli-");
        Path project = Path.of("projects/streaming").toAbsolutePath();
        try {
            Path classes = root.resolve("classes");
            Path source = project.resolve("src/main/ironwood/org/ironwood/streaming/Streaming.iron");
            assertMainRun(new String[]{source.toString(), "--source-path", project.resolve("src/main/ironwood").toString(),
                    "-d", classes.toString()}, 0, "stream CLI source path");
            Path archive = root.resolve("cli.ironjar");
            runCommand(List.of(Path.of("bin/ironjar").toAbsolutePath().toString(), "--create", "--file",
                    archive.toString(), classes.toString()), "CLI archive");
            byte[] binary = new byte[100_003];
            for (int index = 0; index < binary.length; index++) { binary[index] = (byte) index; }
            Path input = root.resolve("input.bin"); Files.write(input, binary);
            Path copied = root.resolve("copied.bin");
            for (int level : List.of(3)) {
                Path executable = root.resolve("streaming-O" + level);
                String cp = (level % 2 == 0 ? classes : archive).toString();
                assertMainRun(new String[]{"--link", "-cp", cp, "--main-class", "org.ironwood.streaming.Streaming",
                        "-o", executable.toString(), "-O" + level}, 0, "stream CLI separate link");
                NativeResult copy = runNative(executable, root, Map.of(), "cp", input.toString(), copied.toString());
                assertEquals(0, copy.exit(), copy.stderr());
                assertTrue(java.util.Arrays.equals(binary, Files.readAllBytes(copied)), "binary cp changed bytes");
                Process cat = new ProcessBuilder(executable.toString(), "cat", input.toString()).start();
                assertTrue(java.util.Arrays.equals(binary, cat.getInputStream().readAllBytes()), "binary cat changed bytes");
                assertEquals(0, cat.waitFor(), "cat exit");
                Path text = root.resolve("text.txt"); Files.writeString(text, "hello 😀\n");
                NativeResult count = runNative(executable, root, Map.of(), "wc", text.toString());
                assertEquals("11 9 2 1\n", count.stdout(), "stream wc");
                assertEquals(0, count.exit(), count.stderr());
                Process stdin = new ProcessBuilder(executable.toString(), "cat").redirectInput(input.toFile()).start();
                assertTrue(java.util.Arrays.equals(binary, stdin.getInputStream().readAllBytes()), "stdin cat changed bytes");
                assertEquals(0, stdin.waitFor(), "stdin cat exit");
                Process prompt = new ProcessBuilder(executable.toString(), "prompt").redirectInput(text.toFile()).start();
                assertEquals("Enter a line: UTF-16 characters: 8\n", new String(prompt.getInputStream().readAllBytes(), StandardCharsets.UTF_8), "interactive prompt");
                assertEquals(0, prompt.waitFor(), "prompt exit");
                Files.writeString(text, "x".repeat(8191) + "😀\r\nend");
                Process stdinCount = new ProcessBuilder(executable.toString(), "wc").redirectInput(text.toFile()).start();
                assertEquals("8200 8198 2 1\n", new String(stdinCount.getInputStream().readAllBytes(), StandardCharsets.UTF_8), "chunk-boundary wc");
                assertEquals(0, stdinCount.waitFor(), "stdin wc exit");
                Path alias = root.resolve("alias-" + level);
                Files.createLink(alias, input);
                assertEquals(74, runNative(executable, root, Map.of(), "cp", input.toString(), alias.toString()).exit(), "hard-link cp");
                assertEquals(74, runNative(executable, root, Map.of(), "cp", input.toString(), input.toString()).exit(), "same-file cp");
                assertTrue(java.util.Arrays.equals(binary, Files.readAllBytes(input)), "same-file cp truncated input");
                assertEquals(64, runNative(executable, root, Map.of()).exit(), "CLI usage");
                assertEquals(74, runNative(executable, root, Map.of(), "cat", root.resolve("missing").toString()).exit(), "missing input");
            }
        } finally { deleteTree(root); }
    }

    private void miniteeProjectRunsAcrossArtifacts() throws Exception {
        Path root = Files.createTempDirectory("ironwood-minitee-cli-");
        Path project = Path.of("projects/minitee").toAbsolutePath();
        try {
            Path classes = root.resolve("classes");
            assertMainRun(new String[]{project.resolve("src/main/ironwood/org/ironwood/minitee/Minitee.iron").toString(),
                    "--source-path", project.resolve("src/main/ironwood").toString(), "-d", classes.toString()},
                    0, "minitee source discovery");
            Path archive = root.resolve("minitee.ironjar");
            assertEquals(0, IronJarMain.run(new String[]{"--create", "--file", archive.toString(), classes.toString()},
                    new PrintStream(new ByteArrayOutputStream()), new PrintStream(new ByteArrayOutputStream())),
                    "minitee archive");
            byte[] binary = new byte[1_048_593];
            for (int index = 0; index < binary.length; index++) { binary[index] = (byte) index; }
            Path input = root.resolve("input.bin"); Files.write(input, binary);
            Path empty = root.resolve("empty.bin"); Files.write(empty, new byte[0]);
            Path output = root.resolve("copy 🌲.bin");
            for (int level : List.of(3)) {
                Path executable = root.resolve("minitee-O" + level);
                assertMainRun(new String[]{"--link", "-cp", (level % 2 == 0 ? classes : archive).toString(),
                        "--main-class", "org.ironwood.minitee.Minitee", "-o", executable.toString(), "-O" + level},
                        0, "minitee native link");
                Files.writeString(output, "old destination content");
                assertMiniteeCopy(executable, root, input, output, binary, binary, "copy 🌲.bin");
                byte[] appended = new byte[binary.length * 2];
                System.arraycopy(binary, 0, appended, 0, binary.length);
                System.arraycopy(binary, 0, appended, binary.length, binary.length);
                assertMiniteeCopy(executable, root, input, output, binary, appended, "-a", "copy 🌲.bin");
                assertMiniteeCopy(executable, root, empty, output, new byte[0], appended, "-a", "copy 🌲.bin");
                assertMiniteeCopy(executable, root, empty, output, new byte[0], new byte[0], "copy 🌲.bin");
                assertMiniteeCopy(executable, root, input, root.resolve("-a"), binary, binary, "--", "-a");
                Path created = root.resolve("append-created-" + level);
                assertMiniteeCopy(executable, root, input, created, binary, binary, "-a", "--", created.toString());
                for (String[] arguments : List.of(new String[0], new String[]{"-a"}, new String[]{"--"},
                        new String[]{"--unknown"}, new String[]{""}, new String[]{"-a", "-a", "unused"},
                        new String[]{"unused", "extra"})) {
                    NativeResult result = runNative(executable, root, Map.of(), arguments);
                    assertEquals(64, result.exit(), "minitee usage");
                    assertEquals("", result.stdout(), "usage must not corrupt stdout");
                    assertContains(result.stderr(), "usage: minitee [-a] [--] file", "usage diagnostic");
                }
                assertTrue(!Files.exists(root.resolve("unused")), "invalid arguments created a file");
                NativeResult missing = runNative(executable, root, Map.of(), "missing/child.bin");
                assertEquals(74, missing.exit(), "minitee missing parent");
                assertEquals("", missing.stdout(), "open failure stdout");
                assertContains(missing.stderr(), "minitee:", "open failure diagnostic");
                assertEquals(74, runNative(executable, root, Map.of(), ".").exit(), "directory output");
                if (level == 3) { assertMiniteeInteractive(executable, root); }
            }
        } finally { deleteTree(root); }
    }

    private void assertMiniteeCopy(Path executable, Path root, Path input, Path output,
                                    byte[] stdout, byte[] file, String... arguments) throws Exception {
        Path capture = root.resolve("stdout.bin");
        List<String> command = new ArrayList<>(List.of(executable.toString()));
        command.addAll(List.of(arguments));
        ProcessBuilder builder = new ProcessBuilder(command).directory(root.toFile())
                .redirectInput(input.toFile()).redirectOutput(capture.toFile());
        builder.environment().remove("IRONWOOD_ALLOCATION_LIMIT");
        Process process = builder.start();
        String error = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
        assertEquals(0, process.waitFor(), "minitee copy: " + error);
        assertEquals("", error, "minitee success stderr");
        assertTrue(java.util.Arrays.equals(stdout, Files.readAllBytes(capture)), "minitee changed stdout bytes");
        assertTrue(java.util.Arrays.equals(file, Files.readAllBytes(output)), "minitee changed file bytes");
    }

    private void assertMiniteeInteractive(Path executable, Path root) throws Exception {
        byte[] chunk = new byte[]{0, (byte) 255, 10, 13, 42};
        Path output = root.resolve("interactive.bin");
        Process process = new ProcessBuilder(executable.toString(), output.toString()).start();
        try {
            process.getOutputStream().write(chunk); process.getOutputStream().flush();
            var received = java.util.concurrent.CompletableFuture.supplyAsync(() -> {
                try { return process.getInputStream().readNBytes(chunk.length); }
                catch (IOException error) { throw new java.io.UncheckedIOException(error); }
            });
            assertTrue(java.util.Arrays.equals(chunk, received.get(5, java.util.concurrent.TimeUnit.SECONDS)),
                    "minitee buffered stdout until EOF");
            assertTrue(java.util.Arrays.equals(chunk, Files.readAllBytes(output)), "file did not receive live input");
            process.getOutputStream().close();
            assertTrue(process.waitFor(5, java.util.concurrent.TimeUnit.SECONDS), "minitee did not finish at EOF");
            assertEquals(0, process.exitValue(), "minitee interactive exit");
            assertEquals("", new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8),
                    "minitee interactive stderr");
        } finally { process.destroyForcibly(); }
    }

    private void miniteeResourcesRunNatively() throws Exception {
        Path root = Files.createTempDirectory("ironwood-minitee-resources-");
        Path sources = Path.of("projects/minitee/src/main/ironwood").toAbsolutePath();
        try {
            Path classes = root.resolve("streams");
            Path lifecycle = root.resolve("lifecycle");
            assertMainRun(new String[]{"integration-tests/cases/minitee_streams.iron", "--source-path",
                    sources.toString(), "-d", classes.toString()}, 0, "minitee stream fixture");
            assertMainRun(new String[]{"integration-tests/cases/minitee_lifecycle.iron", "--source-path",
                    sources.toString(), "-d", lifecycle.toString()}, 0, "minitee lifecycle fixture");
            for (int level : List.of(3)) {
                Path executable = root.resolve("streams-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(), "--main-class",
                        "org.ironwood.minitee.StreamChecks", "-o", executable.toString(), "-O" + level},
                        0, "minitee stream checks link");
                for (String mode : List.of("small", "large", "empty", "read", "zero", "write", "byte", "flush", "close")) {
                    NativeResult result = runNative(executable, root, Map.of(), mode);
                    assertEquals(42, result.exit(), "minitee " + mode + " -O" + level + ": " + result.stderr());
                    assertEquals("", result.stdout(), "stream checks stdout");
                    assertEquals("", result.stderr(), "stream checks stderr");
                }
                Path repeated = root.resolve("lifecycle-O" + level);
                assertMainRun(new String[]{"--link", "-cp", lifecycle.toString(), "--main-class",
                        "org.ironwood.minitee.LifecycleChecks", "-o", repeated.toString(), "-O" + level},
                        0, "minitee lifecycle link");
                Process stress = new ProcessBuilder("/bin/sh", "-c", "ulimit -n 32; exec \"$@\" < /dev/null",
                        "minitee-test", repeated.toString(), root.resolve("stress.bin").toString()).start();
                String stressError = new String(stress.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
                assertEquals(42, stress.waitFor(), "minitee descriptor stress: " + stressError);
                assertEquals("", stressError, "descriptor stress stderr");
                for (int limit = 0; limit <= 2; limit++) {
                    ProcessBuilder builder = new ProcessBuilder(repeated.toString(), root.resolve("oom.bin").toString())
                            .redirectInput(Path.of("/dev/null").toFile());
                    builder.environment().put("IRONWOOD_ALLOCATION_LIMIT", Integer.toString(limit));
                    Process process = builder.start();
                    String error = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
                    assertEquals(43, process.waitFor(), "minitee OOM " + limit + ": " + error);
                    assertEquals("", error, "minitee OOM stderr");
                }
                Path cli = root.resolve("cli-O" + level);
                assertMainRun(new String[]{"--link", "-cp", lifecycle.toString(), "--main-class",
                        "org.ironwood.minitee.Minitee", "-o", cli.toString(), "-O" + level},
                        0, "minitee fault CLI link");
                byte[] payload = "sample input\n".getBytes(StandardCharsets.UTF_8);
                Path input = root.resolve("input.bin"); Files.write(input, payload);
                for (String mode : List.of("read", "file-write", "stdout")) {
                    String script = switch (mode) {
                        case "read" -> "exec \"$@\" 0<.";
                        case "file-write" -> "trap '' XFSZ; ulimit -f 0; exec \"$@\"";
                        default -> "exec \"$@\" 1</dev/null";
                    };
                    Path output = root.resolve(mode + ".bin");
                    Process process = new ProcessBuilder("/bin/sh", "-c", script, "minitee-test",
                            cli.toString(), output.toString()).directory(root.toFile())
                            .redirectInput(input.toFile()).start();
                    byte[] actual = process.getInputStream().readAllBytes();
                    String error = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
                    assertEquals(74, process.waitFor(), "minitee " + mode + " fault: " + error);
                    assertContains(error, "minitee:", "minitee native I/O diagnostic");
                    assertTrue(java.util.Arrays.equals(mode.equals("file-write") ? payload : new byte[0], actual),
                            "fault changed stdout unexpectedly");
                    assertTrue(java.util.Arrays.equals(mode.equals("stdout") ? payload : new byte[0], Files.readAllBytes(output)),
                            "fault changed destination unexpectedly");
                }
            }
            CompilationArtifact borrowed = new CompilerPipeline().compile(List.of(
                    SourceFile.read(sources.resolve("org/ironwood/minitee/TeeOutputStream.iron")),
                    SourceFile.of("test/Main.iron", """
                            package org.ironwood.minitee;
                            import ironwood.io.ByteArrayOutputStream;
                            class Main {
                                public static int main(String[] args) {
                                    ByteArrayOutputStream sink = new ByteArrayOutputStream();
                                    TeeOutputStream tee = new TeeOutputStream(sink, sink);
                                    free sink; free tee; return 42;
                                }
                            }
                            """)));
            assertTrue(!borrowed.successful(), "tee's live output borrow was ignored");
            assertContains(messages(borrowed), "cannot free 'sink'", "tee retained borrow diagnostic");
        } finally { deleteTree(root); }
    }

    private void u2FilesRunAtAllOptimizationLevels() throws Exception {
        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        Path fixture = projectRoot.resolve("integration-tests/cases/stdlib_u2_files.iron");
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path root = Files.createTempDirectory("ironwoodc-u2-files-");
        Path denied = root.resolve("denied.txt");
        boolean permissionExpected = false;
        try {
            Files.write(root.resolve("malformed.bin"), new byte[]{(byte) 0xc3, (byte) 0x28});
            Files.writeString(root.resolve("empty.txt"), "", StandardCharsets.UTF_8);
            Files.writeString(root.resolve("large.txt"), "x".repeat(1_048_576),
                    StandardCharsets.UTF_8);
            Files.writeString(denied, "denied", StandardCharsets.UTF_8);
            try {
                Files.setPosixFilePermissions(denied, Set.of());
                permissionExpected = !Files.isReadable(denied);
            } catch (UnsupportedOperationException ignored) {
                permissionExpected = false;
            }

            Path classes = root.resolve("classes");
            assertMainRun(new String[]{fixture.toString(), "-d", classes.toString()}, 0,
                    "U2 file fixture compilation");
            for (int level : List.of(3)) {
                Path executable = root.resolve("files-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(),
                                "--main-class", "Main", "-o", executable.toString(),
                                "-O" + level, "--llvm-home", toolchain.home().toString()},
                        0, "U2 file fixture -O" + level + " link");
                NativeResult result = runNative(executable, root, Map.of(),
                        root.toString(), Boolean.toString(permissionExpected));
                assertEquals(42, result.exit(), "U2 file fixture -O" + level + " exit");
                assertEquals("", result.stdout(), "U2 file fixture -O" + level + " stdout");
                assertEquals("", result.stderr(), "U2 file fixture -O" + level + " stderr");
            }
        } finally {
            try {
                Files.setPosixFilePermissions(denied,
                        PosixFilePermissions.fromString("rw-------"));
            } catch (IOException | UnsupportedOperationException ignored) {
                // Best-effort restoration keeps cleanup portable on non-POSIX hosts.
            }
            deleteTree(root);
        }
    }

