    private void pathScratchAllocationMatchesJava() throws Exception {
        List<String> inputs = new ArrayList<>(List.of("", "/", "//", "///a//", "a/..",
                "a/../../b", "../a/..", "/a/../../b", "a/./b/../c", ".", "..",
                "../../a/../b", "a/.../b", "🌲/é/../z", "a/../../b/../c",
                "./.././a///../", "a/../".repeat(2000) + "🌲"));
        java.util.Random random = new java.util.Random(304);
        String[] names = {"a", "é", "🌲", ".", "..", "...", ""};
        for (int sample = 0; sample < 100; sample++) {
            StringBuilder path = new StringBuilder(sample % 2 == 0 ? "/" : "");
            for (int part = 0; part < 12; part++) {
                path.append(names[random.nextInt(names.length)]).append('/');
            }
            inputs.add(path.toString());
        }
        Path directory = Files.createTempDirectory("ironwood-path-scratch-");
        try {
            StringBuilder expected = new StringBuilder();
            Path other = Path.of("../z//🌲/");
            for (String input : inputs) {
                Path path = Path.of(input);
                Path absolute = path.isAbsolute() ? path : directory.toRealPath().resolve(path);
                Path[] results = {path, path.normalize(), path.getFileName(), path.getParent(),
                        path.getRoot(), absolute, path.resolve("../z//🌲/"), path.resolve(other),
                        path.resolveSibling("../z//🌲/"), path.resolveSibling(other),
                        path.resolve(""), path.resolve("///fixed//leaf/")};
                for (Path result : results) {
                    expected.append(result == null ? "<null>" : result.toString()).append('\n');
                }
            }
            Path classes = directory.resolve("classes");
            assertMainRun(new String[]{"integration-tests/cases/stdlib_path_scratch.iron",
                    "-d", classes.toString()}, 0, "path scratch compilation");
            for (int level : List.of(3)) {
                Path executable = directory.resolve("path-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(), "--main-class",
                        "Main", "-o", executable.toString(), "-O" + level}, 0, "path scratch link");
                NativeResult result = runNative(executable, directory, Map.of(),
                        inputs.toArray(String[]::new));
                assertEquals(42, result.exit(), "path scratch -O" + level + " exit");
                assertEquals(expected.toString(), result.stdout(), "path Java differential");
                assertEquals("", result.stderr(), "path scratch stderr");
            }
        } finally { deleteTree(directory); }
    }

