    private void runNativeRuntimeHarness(String fixture) throws Exception {
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path root = Files.createTempDirectory("ironwood-native-scratch-");
        try {
            for (int level : List.of(3)) {
                Path object = root.resolve("scratch-O" + level + ".o");
                Path executable = root.resolve("scratch-O" + level);
                runCommand(List.of(toolchain.clang().toString(), "-std=c11", "-O" + level,
                        "-c", "integration-tests/runtime/" + fixture, "-o", object.toString()),
                        "native scratch harness compilation");
                Path caseObject = root.resolve("case.o");
                runCommand(List.of(toolchain.clang().toString(), "-std=c11", "-O3", "-c",
                        "runtime/src/ironwood_case.c", "-o", caseObject.toString()), "Unicode helper compilation");
                runCommand(List.of(toolchain.clang().toString(), "--driver-mode=g++",
                        object.toString(), caseObject.toString(), "-o", executable.toString()), "native scratch harness link");
                NativeResult result = runNative(executable, root, Map.of(), root.toString());
                assertEquals(0, result.exit(), "native scratch -O" + level + ": " + result.stderr());
                assertEquals("", result.stderr(), "native scratch stderr");
            }
        } finally { deleteTree(root); }
    }

    private void minigrepProjectRunsAcrossDistributionForms() throws Exception {
        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        Path minigrep = projectRoot.resolve("projects/minigrep");
        Path source = minigrep.resolve(
                "src/main/ironwood/org/ironwood/minigrep/Minigrep.iron");
        Path sourceRoot = minigrep.resolve("src/main/ironwood");
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path root = Files.createTempDirectory("ironwoodc-minigrep-");
        Path denied = root.resolve("denied.txt");
        boolean permissionExpected = false;
        try {
            Path classes = root.resolve("classes");
            assertMainRun(new String[]{"--source-path", sourceRoot.toString(), "-d",
                            classes.toString(), source.toString()},
                    0, "minigrep source compilation");
            assertTrue(Files.isRegularFile(classes.resolve(
                            "org/ironwood/minigrep/Minigrep.ironclass")),
                    "minigrep main loose class is missing");
            assertTrue(Files.isRegularFile(classes.resolve(
                            "org/ironwood/minigrep/Search.ironclass")),
                    "minigrep search loose class is missing");

            Path input = root.resolve("input🌲.txt");
            String inputText = "alpha\r\nRust:\r\nsafe 🌲 line\nDuct tape.\nlast needle";
            Files.writeString(input, inputText, StandardCharsets.UTF_8);
            Path empty = root.resolve("empty.txt");
            Files.writeString(empty, "", StandardCharsets.UTF_8);
            Path large = root.resolve("large.txt");
            Files.writeString(large, "padding\n".repeat(150_000) + "final target",
                    StandardCharsets.UTF_8);
            Path malformed = root.resolve("malformed.bin");
            Files.write(malformed, new byte[]{(byte) 0xc3, (byte) 0x28});
            Files.writeString(denied, "secret", StandardCharsets.UTF_8);
            try {
                Files.setPosixFilePermissions(denied, Set.of());
                permissionExpected = !Files.isReadable(denied);
            } catch (UnsupportedOperationException ignored) {
                permissionExpected = false;
            }

            for (int level : List.of(3)) {
                Path executable = root.resolve("minigrep-O" + level);
                assertMainRun(new String[]{"--link", "-cp", classes.toString(),
                                "--main-class", "org.ironwood.minigrep.Minigrep",
                                "-o", executable.toString(), "-O" + level,
                                "--llvm-home", toolchain.home().toString()},
                        0, "minigrep loose-class -O" + level + " link");
                assertMinigrepBehavior(executable, root, input, empty, large, malformed,
                        denied, permissionExpected, "loose-class -O" + level);
            }

            Path archive = root.resolve("minigrep.ironjar");
            ByteArrayOutputStream archiveError = new ByteArrayOutputStream();
            int archiveExit = IronJarMain.run(new String[]{"--create", "--file",
                            archive.toString(), classes.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(archiveError, true, StandardCharsets.UTF_8));
            assertEquals(0, archiveExit, "minigrep archive creation; stderr: "
                    + archiveError.toString(StandardCharsets.UTF_8));
            for (int level : List.of(3)) {
                Path executable = root.resolve("minigrep-archive-O" + level);
                assertMainRun(new String[]{"--link", "-cp", archive.toString(),
                                "--main-class", "org.ironwood.minigrep.Minigrep",
                                "-o", executable.toString(), "-O" + level,
                                "--llvm-home", toolchain.home().toString()},
                        0, "minigrep archive -O" + level + " link");
                NativeResult result = runNative(executable, root, Map.of(),
                        "needle", input.toString());
                assertEquals(0, result.exit(), "minigrep archive -O" + level + " exit");
                assertEquals("last needle\n", result.stdout(),
                        "minigrep archive -O" + level + " stdout");
                assertEquals("", result.stderr(),
                        "minigrep archive -O" + level + " stderr");
            }

            Set<String> stdlibTypes = IronJar.read(
                    projectRoot.resolve("compiler/build/ironwood-stdlib.ironjar"))
                    .declaredTypes();
            assertTrue(stdlibTypes.contains("ironwood.io.IOException"),
                    "standard-library archive does not index IOException");
            assertTrue(stdlibTypes.contains("ironwood.nio.file.Path"),
                    "standard-library archive does not index Path");
            assertTrue(stdlibTypes.contains("ironwood.nio.file.Paths"),
                    "standard-library archive does not index Paths");
            assertTrue(stdlibTypes.contains("ironwood.nio.file.Files"),
                    "standard-library archive does not index Files");
        } finally {
            try {
                Files.setPosixFilePermissions(denied,
                        PosixFilePermissions.fromString("rw-------"));
            } catch (IOException | UnsupportedOperationException ignored) {
                // Best-effort restoration keeps cleanup portable on non-POSIX hosts.
            }
            deleteTree(root);
        }
    }

    private void assertMinigrepBehavior(Path executable, Path directory, Path input,
                                        Path empty, Path large, Path malformed, Path denied,
                                        boolean permissionExpected, String label) throws Exception {
        NativeResult exact = runNative(executable, directory, Map.of(),
                "needle", input.toString());
        assertEquals(0, exact.exit(), label + " exact-match exit");
        assertEquals("last needle\n", exact.stdout(), label + " exact-match stdout");
        assertEquals("", exact.stderr(), label + " exact-match stderr");

        NativeResult unicode = runNative(executable, directory, Map.of(),
                "🌲", input.toString());
        assertEquals(0, unicode.exit(), label + " Unicode exit");
        assertEquals("safe 🌲 line\n", unicode.stdout(), label + " Unicode stdout");

        NativeResult insensitive = runNative(executable, directory,
                Map.of("IGNORE_CASE", "1"), "rUsT", input.toString());
        assertEquals(0, insensitive.exit(), label + " ignore-case exit");
        assertEquals("Rust:\n", insensitive.stdout(), label + " ignore-case stdout");

        NativeResult allLines = runNative(executable, directory, Map.of(),
                "", input.toString());
        assertEquals(0, allLines.exit(), label + " empty-query exit");
        assertEquals("alpha\nRust:\nsafe 🌲 line\nDuct tape.\nlast needle\n",
                allLines.stdout(), label + " LF/CRLF/final-line stdout");

        NativeResult noMatch = runNative(executable, directory, Map.of(),
                "absent", input.toString());
        assertEquals(1, noMatch.exit(), label + " no-match exit");
        assertEquals("", noMatch.stdout(), label + " no-match stdout");
        assertEquals("", noMatch.stderr(), label + " no-match stderr");

        NativeResult emptyFile = runNative(executable, directory, Map.of(),
                "anything", empty.toString());
        assertEquals(1, emptyFile.exit(), label + " empty-file exit");

        NativeResult largeFile = runNative(executable, directory, Map.of(),
                "target", large.toString());
        assertEquals(0, largeFile.exit(), label + " large-file exit");
        assertEquals("final target\n", largeFile.stdout(), label + " large-file stdout");

        NativeResult usage = runNative(executable, directory, Map.of());
        assertEquals(64, usage.exit(), label + " usage exit");
        assertEquals("", usage.stdout(), label + " usage stdout");
        assertEquals("usage: minigrep <literal-query> <path>\n", usage.stderr(),
                label + " usage stderr");

        Path missing = directory.resolve("missing.txt");
        NativeResult missingFile = runNative(executable, directory, Map.of(),
                "query", missing.toString());
        assertEquals(74, missingFile.exit(), label + " missing-file exit");
        assertEquals("", missingFile.stdout(), label + " missing-file stdout");
        assertEquals("minigrep: " + missing + "\n", missingFile.stderr(),
                label + " missing-file stderr");

        NativeResult invalidUtf8 = runNative(executable, directory, Map.of(),
                "query", malformed.toString());
        assertEquals(74, invalidUtf8.exit(), label + " malformed UTF-8 exit");
        assertEquals("minigrep: " + malformed + ": Input is not valid UTF-8\n",
                invalidUtf8.stderr(), label + " malformed UTF-8 stderr");

        if (permissionExpected) {
            NativeResult permission = runNative(executable, directory, Map.of(),
                    "query", denied.toString());
            assertEquals(74, permission.exit(), label + " permission exit");
            assertEquals("minigrep: " + denied + ": Permission denied\n",
                    permission.stderr(), label + " permission stderr");
        }
    }

    private NativeResult runNative(Path executable, Path directory,
                                   Map<String, String> environment,
                                   String... arguments) throws Exception {
        List<String> command = new ArrayList<>();
        command.add(executable.toString());
        command.addAll(List.of(arguments));
        ProcessBuilder builder = new ProcessBuilder(command).directory(directory.toFile());
        builder.environment().remove("IGNORE_CASE");
        builder.environment().remove("IRONWOOD_ALLOCATION_LIMIT");
        builder.environment().putAll(environment);
        Process process = builder.start();
        String stdout = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        String stderr = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
        return new NativeResult(process.waitFor(), stdout, stderr);
    }

