    private void stringConcatenationFormatsFloatingPointLikeJava() throws Exception {
        NativeResult result = compileAndRunNative("Main.iron", """
                class Main {
                    static float f(float value) { return value; }
                    static double d(double value) { return value; }
                    public static int main(String[] args) {
                        String text = "" + f(1.4e-45f) + '|' + f(1.17549435e-38f)
                                + '|' + f(1.2345678f) + '|' + f(9999999.0f)
                                + '|' + f(10000000.0f) + '|' + f(3.4028235e38f)
                                + '|' + d(4.9e-324) + '|' + d(2.2250738585072014e-308)
                                + '|' + d(1.2345678901234567) + '|' + d(9999999.0)
                                + '|' + d(10000000.0) + '|' + d(1.7976931348623157e308);
                        System.out.println(text);
                        return 42;
                    }
                }
                """, "Main", "-O3");
        String expected = Float.toString(Float.MIN_VALUE) + '|'
                + Float.toString(Float.MIN_NORMAL) + '|' + Float.toString(1.2345678f) + '|'
                + Float.toString(9999999.0f) + '|' + Float.toString(10000000.0f) + '|'
                + Float.toString(Float.MAX_VALUE) + '|' + Double.toString(Double.MIN_VALUE) + '|'
                + Double.toString(Double.MIN_NORMAL) + '|'
                + Double.toString(1.2345678901234567) + '|' + Double.toString(9999999.0) + '|'
                + Double.toString(10000000.0) + '|' + Double.toString(Double.MAX_VALUE) + "\n";
        assertEquals(42, result.exit(), "floating-point concatenation exit");
        assertEquals(expected, result.stdout(), "floating-point concatenation text");
        assertEquals("", result.stderr(), "floating-point concatenation stderr");
    }

    private void unusedVirtualMethodsDoNotRetainStringCasing() throws Exception {
        CompilationArtifact unused = compile("class Main { public static int main(String[] args) { return 42; } }");
        assertTrue(unused.successful(), messages(unused));
        IrProgram pruned = ClosedWorldPruner.prune(unused.program().orElseThrow());
        assertTrue(pruned.functions().stream().noneMatch(function ->
                function.ownerClass().equals("ironwood.lang.String")
                        && List.of("toUpperCase", "toLowerCase", "equalsIgnoreCase", "caseValue")
                            .contains(function.sourceName())), "unused String operations remain reachable");
        CompilationArtifact used = compile("""
                interface Operation { String run(); }
                class Upper implements Operation { @Override public String run() { return "ß".toUpperCase(); } }
                class Lower implements Operation { @Override public String run() { return "ΟΣ".toLowerCase(); } }
                class Main {
                    static int apply(Operation operation) {
                        String value = operation.run();
                        return value.length();
                    }
                    public static int main(String[] args) {
                        Operation selected = args.length == 0 ? (Operation) new Upper() : (Operation) new Lower();
                        return apply(selected);
                    }
                }
                """);
        assertTrue(used.successful(), messages(used));
        IrProgram withCalls = ClosedWorldPruner.prune(used.program().orElseThrow());
        for (String owner : List.of("Upper", "Lower")) {
            assertTrue(withCalls.functions().stream().anyMatch(function ->
                    function.ownerClass().equals(owner) && function.sourceName().equals("run")),
                    "pruning lost a reachable interface override: " + owner);
        }
        assertTrue(containsInstruction(withCalls, ironwood.compiler.ir.IrStringCaseInstruction.class),
                "pruning lost reachable Unicode conversion");
    }

