    private void assertNativeFailure(String sourceText, String expectedStderr,
                                     boolean requireExitOne) throws Exception {
        Path temporaryDirectory = Files.createTempDirectory("ironwoodc-native-failure-");
        try {
            Path source = writeSource(temporaryDirectory, "Main.iron", sourceText);
            Path classes = temporaryDirectory.resolve("classes");
            ByteArrayOutputStream compileError = new ByteArrayOutputStream();
            int compilerExit = Main.run(new String[]{source.toString(), "-d", classes.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(compileError, true, StandardCharsets.UTF_8));
            assertEquals(0, compilerExit, "exception failure fixture compiler exit; stderr: "
                    + compileError.toString(StandardCharsets.UTF_8));
            Path executable = temporaryDirectory.resolve("program");
            LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
            ByteArrayOutputStream linkError = new ByteArrayOutputStream();
            int linkExit = Main.run(new String[]{"--link", "-cp", classes.toString(),
                            "--main-class", "Main", "-o", executable.toString(),
                            "-O3", "--llvm-home", toolchain.home().toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(linkError, true, StandardCharsets.UTF_8));
            assertEquals(0, linkExit, "exception failure fixture link exit; stderr: "
                    + linkError.toString(StandardCharsets.UTF_8));
            Process process = new ProcessBuilder(executable.toString()).start();
            String stderr = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
            int exit = process.waitFor();
            if (requireExitOne) {
                assertEquals(1, exit, "native failure process exit code");
            } else {
                assertTrue(exit != 0, "native failure unexpectedly exited successfully");
            }
            if (!expectedStderr.isEmpty()) {
                assertContains(stderr, expectedStderr, "native failure diagnostic");
            }
        } finally {
            deleteTree(temporaryDirectory);
        }
    }

