    private void runFixtureAtO3(String fixtureName, String mainClass,
                                                   int expectedExit, String expectedOutput,
                                                   String expectedError,
                                                   Map<String, String> environment) throws Exception {
        Path projectRoot = Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();
        Path fixture = projectRoot.resolve("integration-tests/cases").resolve(fixtureName);
        LlvmToolchain toolchain = LlvmToolchain.discover(null).toolchain().orElseThrow();
        Path temporaryDirectory = Files.createTempDirectory("ironwoodc-optimization-test-");
        try {
            Path classes = temporaryDirectory.resolve("classes");
            ByteArrayOutputStream compileError = new ByteArrayOutputStream();
            int compilerExit = Main.run(new String[]{fixture.toString(), "-d", classes.toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(compileError, true, StandardCharsets.UTF_8));
            assertEquals(0, compilerExit, "fixture compiler exit; stderr: "
                    + compileError.toString(StandardCharsets.UTF_8));
            int level = 3;
            Path executable = temporaryDirectory.resolve("program-O" + level);
            ByteArrayOutputStream stderr = new ByteArrayOutputStream();
            int linkExit = Main.run(new String[]{"--link", "-cp", classes.toString(),
                            "--main-class", mainClass,
                            "-o", executable.toString(),
                            "-O" + level, "--llvm-home", toolchain.home().toString()},
                    new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8),
                    new PrintStream(stderr, true, StandardCharsets.UTF_8));
            assertEquals(0, linkExit,
                    "-O" + level + " link exit code; stderr: " + stderr.toString(StandardCharsets.UTF_8));
            ProcessBuilder processBuilder = new ProcessBuilder(executable.toString());
            processBuilder.environment().putAll(environment);
            Process process = processBuilder.start();
            String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
            String error = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8);
            int nativeExit = process.waitFor();
            assertEquals(expectedExit, nativeExit, "-O" + level + " native process exit code");
            if (expectedOutput != null) {
                assertEquals(expectedOutput, output, "-O" + level + " standard output");
            }
            if (expectedError != null) {
                assertEquals(expectedError, error, "-O" + level + " standard error");
            }
        } finally {
            deleteTree(temporaryDirectory);
        }
    }

