    private ironwood.compiler.parser.ParseResult parseOnly(String text) {
        SourceFile source = SourceFile.of("test/ParserFoundation.iron", text);
        var lexed = new ironwood.compiler.lexer.Lexer(source).lex();
        assertTrue(lexed.diagnostics().isEmpty(), lexed.diagnostics().toString());
        return new ironwood.compiler.parser.Parser(source, lexed.tokens()).parse();
    }

